/* 江湖一生 · incidents: life inside the righteous and neutral sects — chores, rivalries, festivals, canon flavour, and missions */
'use strict';
const scOK=s=>!!s.sect&&!isEvil(s.sect)&&!s.retired;
const scIs=(...ids)=>s=>scOK(s)&&ids.includes(s.sect);
const scNm=s=>T(SECTS[s.sect].en,SECTS[s.sect].cn);
const scSib=(p,s)=>{const old=p.age>=s.age;return p.sex==='m'?(old?T('senior brother','师兄'):T('junior brother','师弟')):(old?T('senior sister','师姐'):T('junior sister','师妹'))};
const scSexOf=s=>s.sect==='shaolin'?'m':(s.sect==='yihua'||s.sect==='gumu')?'f':s.sect==='emei'?(chance(.75)?'f':'m'):null;
/* a fellow disciple: half the time one you already know */
function scFellow(s,c,o){o=o||{};const sx=o.sex||scSexOf(s);
  const f=o.fresh?[]:living(s,'fellow').filter(p=>!sx||p.sex===sx);
  if(f.length&&chance(.5)){const p=pick(f);c.npc=Object.assign(npc(s,{sex:p.sex,age:p.age,lv:p.lv,occ:13}),{n:p.n,en:p.n.py,zh:p.n.cn});c.pid=p.id}
  else{const a=o.age??clamp(s.age+rint(-3,5),12,70);c.npc=npc(s,{sex:sx||(chance(.5)?'m':'f'),age:a,lv:o.lv??Math.max(3,Math.round(power(s)+rint(-6,8))),occ:13})}
  c.sib=scSib(c.npc,s);return c}
const scCtx=o=>s=>{const c=scene();scFellow(s,c,o);return c};
/* the master's bond moves with fx.bond when there is no other person in the scene */
const scMctx=s=>{const c=scene();const m=masterOf(s);if(m)c.who=m.id;return c};
const scOpp=s=>s.gender==='m'?'f':'m';
const CH=['chore'],SM=['sect'];

/* ====================== everyday sect life (any righteous sect) ====================== */
I({id:'sc_water',age:[11,40],tags:CH,only:1,cd:8,when:scOK,ctx:scMctx,
 text:(c,s)=>T(`Water duty at ${s.sect?SECTS[s.sect].en:'the sect'}: three hundred stone steps, two buckets, before dawn. The steward says the buckets must arrive full, not "mostly full".`,`${SZ(s.sect)}的挑水差事：三百级石阶，两只木桶，天亮前送到。管事说桶要满的，"差不多满"不算。`),
 opts:[{l:T('Carry them steady and slow','稳稳地慢慢挑'),out:[{w:2,t:T('Not a drop spilled. Your legs shake all through morning practice, and the steward grunts, which from him is praise.','一滴未洒。早课时你两腿直打颤。管事哼了一声——这在他已经算夸奖了。'),c:'good',fx:{merit:3,maxHealth:1}},{w:1,t:T('Halfway up you find your breath moving with your steps, as if the buckets were carrying you.','爬到一半，你发觉呼吸竟跟着脚步走，倒像是水桶在带着你上山。'),c:'gold',fx:{merit:3,qi:3}}]},
  {l:T('Run them up with light-body skill','用轻功一口气冲上去'),out:[{w:s=>1+power(s)/60,t:T('You arrive before the bell, buckets brimming. Two younger disciples watch you with their mouths open.','钟还没响你就到了，桶里的水满得晃荡。两个小师弟张着嘴看你。'),c:'good',fx:{merit:4,fame:1,skill:1}},{w:1,t:T('You trip on the ninetieth step. The water goes one way and you go the other.','第九十级台阶上你绊了一跤。水往这边泼，人往那边滚。'),c:'bad',fx:{merit:1,hurt:[2,6],cause:T('a fall on the sect stairs','在山门石阶上摔倒')}}]},
  {l:T('Fill them at the nearer, muddier spring','去近处那口浑泉打水'),out:[{w:2,t:T('The cook spits out the tea and the steward knows exactly why. You carry water for an extra month.','伙房一尝茶就吐了，管事一猜就知道。你被罚多挑一个月水。'),c:'bad',fx:{merit:-2,happy:-2}},{w:1,t:T('Nobody notices. You feel oddly guilty every time someone drinks tea.','没人发觉。可每次看见有人喝茶，你都莫名心虚。'),c:'muted',fx:{merit:2,align:-1}}]}]});

I({id:'sc_wallface',age:[12,45],tags:CH,only:1,cd:12,when:scOK,ctx:scMctx,
 text:()=>T('You are caught where you should not be, and sentenced to face the wall (面壁) for a month in a stone cell, with one bowl of rice a day.','你被抓到出现在不该出现的地方，罚面壁一个月：一间石室，一天一碗米饭。'),
 opts:[{l:T('Really reflect','真心思过'),out:[{w:2,t:T('By the third week the wall stops being a wall. Your breathing slows until you can hear your own pulse in the stone.','到第三个星期，墙不再是墙了。你的呼吸慢下来，慢到能在石头里听见自己的脉搏。'),c:'good',fx:{qi:5,merit:2,bond:3}},{w:1,t:T('You realise you were in the wrong, which is somehow worse than the rice.','你想明白了确实是自己错了。这比那碗米饭还难咽。'),c:'muted',fx:{align:2,merit:2,smarts:1}}]},
  {l:T('Study the scratches on the wall','研究墙上的刻痕'),out:[{w:2,t:T('Someone faced this wall before you, and carved sword moves into it in the dark. Most are nonsense. Three are not.','前人也在这里面过壁，摸黑在墙上刻了些剑招。大多是胡刻乱画，但有三招不是。'),c:'gold',fx:{skill:3}},{w:1,t:T('Under the scratches is a poem about a girl from the kitchens, sixty years old at least. You laugh out loud in the dark.','刻痕底下是一首写给伙房姑娘的情诗，少说也有六十年了。你在黑暗里笑出了声。'),fx:{happy:3}}]},
  {l:T('Slip out at night','夜里溜出去'),out:[{w:2,t:T('You are back by dawn, full of dumplings. Nobody noticed. Probably.','天亮前你回来了，肚子里塞满了饺子。没人发觉。大概。'),c:'muted',fx:{happy:4}},{w:1,t:T('The cell door is open when you return, and your master is sitting inside it. Another month.','回来时石门开着，师父就坐在里面。再加一个月。'),c:'bad',fx:{merit:-3,bond:-4,happy:-3}}]}]});

I({id:'sc_rival',age:[12,35],tags:CH,only:1,cd:10,when:scOK,ctx:scCtx({fresh:1}),
 text:c=>T(`Your ${c.sib.en}, ${c.npc.en}, has decided you are their rival. Whatever you practise, they practise twice. Whatever you eat, they eat more of.`,`${c.sib.zh}${c.npc.zh}认定你是对手了。你练一遍，${c.npc.ta}练两遍；你吃一碗，${c.npc.ta}吃两碗。`),
 opts:[{l:T('Train harder','练得更狠'),out:[{w:2,t:T('You train until your hands bleed. So do they. The elders have never seen two disciples improve so fast or hate each other so politely.','你练到手掌出血。对方也是。长老们从没见过两个弟子长进得这么快，又恨得这么客气。'),c:'good',fx:{skill:3,merit:2,meet:'rival',bond:35}},{w:1,t:T('You both collapse on the same afternoon and share a sickbed, and then a laugh.','你们俩在同一个下午累倒，躺在同一间病房，然后一起笑了。'),c:'good',fx:{skill:1,meet:'friend',bond:60}}]},
  {l:T('Swap their practice sword for a wooden one','把对方的剑换成木剑'),out:[{w:1,t:T('They draw it in front of the master. The whole yard laughs. They will not forget it.','对方当着师父的面拔出了一把木剑，满场哄笑。这仇对方记下了。'),c:'muted',fx:{happy:3,meet:'enemy',bond:15}},{w:1,t:T('They spot it at once, swap it back, and replace your sword with a carrot.','对方一眼就看穿了，换了回来，又把你的剑换成一根萝卜。'),fx:{happy:2}}]},
  {l:T('Ask them to train together','邀对方一起练'),out:[{w:2,t:T('They look suspicious for a month. Then they start showing up before you do.','对方疑神疑鬼了一个月，后来每天比你到得还早。'),c:'good',fx:{meet:'friend',bond:62,skill:1,merit:1}},{w:1,t:T('"I do not need your pity." They train alone, angrier than before.','"用不着你可怜我。"对方独自去练了，比以前更狠。'),c:'muted',fx:{meet:'rival',bond:25}}]}]});

I({id:'sc_peaches',age:[15,32],tags:CH,only:1,cd:12,when:s=>scOK(s)&&s.sect!=='shaolin'&&!spouseOf(s),ctx:s=>{const c=scene();return scFellow(s,c,{sex:scOpp(s),age:clamp(s.age+rint(-2,3),14,40)})},
 text:c=>T(`Every morning there is a peach on your windowsill. On the tenth morning you catch ${c.sib.en} ${c.npc.en} putting it there, and both of you go red to the ears.`,`每天早上你窗台上都有一个桃子。第十天你撞见${c.sib.zh}${c.npc.zh}正往那儿放，两人的脸都红到了耳根。`),
 opts:[{l:T('Leave something in return','回赠一件小东西'),out:[{w:3,t:T('A carved bird, a pressed flower, a note with one line of poetry. By autumn the whole sect knows, and pretends not to.','一只木雕的小鸟，一朵压干的花，一张写着一句诗的纸条。到秋天全派都知道了，又都装不知道。'),c:'good',fx:{meet:'lover',bond:62,happy:7}},{w:1,t:T('The steward finds your note first and reads it aloud at dinner. You both survive, barely.','管事先一步发现了你的纸条，晚饭时当众念了出来。你们俩总算活了下来——勉强。'),c:'muted',fx:{meet:'lover',bond:55,happy:2,merit:-1}}]},
  {l:T('Pretend you saw nothing','装作没看见'),out:[{w:2,t:T('The peaches stop. You miss them more than you expected.','桃子不再来了。你比自己以为的还要想念。'),c:'muted',fx:{happy:-2}},{w:1,t:T('The peaches keep coming. You eat them all and say nothing, for years.','桃子一直没断。你每个都吃了，一句话也没说，就这样好些年。'),fx:{happy:2,meet:'friend',bond:60}}]},
  {l:T('Remind them of the sect rules','提醒对方门规'),out:[{t:T('They bow stiffly and never bring another. The rules are kept. Your windowsill is very clean.','对方僵硬地行了个礼，再没送过。门规是守住了，你的窗台干干净净。'),c:'muted',fx:{merit:2,align:1,happy:-1}}]}]});

I({id:'sc_mood',age:[11,50],tags:CH,only:1,cd:8,when:s=>scOK(s)&&!!masterOf(s),ctx:scMctx,
 text:()=>T('Your master has been in a black mood for a week. Breakfast is silent. Two cups have been broken. Nobody knows why, and everybody is afraid to ask.','师父心情坏了整整一个星期。早饭鸦雀无声，已经摔了两只茶杯。谁也不知道为什么，谁也不敢问。'),
 opts:[{l:T('Ask, gently','小心地问一句'),out:[{w:2,t:T('An old friend has died far away. Your master talks for an hour about the two of them at twenty, then sends you off with a pat on the head.','原来是一位远方的故友过世了。师父讲了一个时辰他们二十岁时的事，然后拍拍你的头让你走了。'),c:'good',fx:{bond:8,merit:2}},{w:1,t:T('"Mind your own practice!" You hold a horse stance until sunset. It does help your legs.','"管好你自己的功课！"你被罚扎马步扎到日落。腿倒是练结实了。'),c:'muted',fx:{skill:1,bond:-2}}]},
  {l:T('Brew the master’s favourite tea','泡一壶师父最爱的茶'),out:[{w:2,t:T('The tea goes untouched until midnight. In the morning the pot is empty and the mood has lifted.','茶一直放到半夜都没人碰。第二天早上壶空了，师父的脸色也晴了。'),c:'good',fx:{bond:5,merit:2}},{w:1,t:T('It was a quarrel over tea, it turns out. The pot goes out of the window.','原来正是为茶吵的架。茶壶飞出了窗外。'),fx:{happy:-1}}]},
  {l:T('Keep your head down','低头做事'),out:[{t:T('You become very good at being invisible. The mood passes in a month, as moods do.','你练成了隐身的本事。过了一个月，坏心情就散了，坏心情向来如此。'),c:'muted',fx:{merit:3}}]}]});

I({id:'sc_festival',age:[11,70],tags:CH,only:1,cd:6,when:scOK,
 text:(c,s)=>T(`It is the founder’s day of ${SECTS[s.sect].en}. Lanterns on every eave, guests from a dozen sects, and an altar of offerings taller than a man. You are given a job.`,`今日是${SZ(s.sect)}的祖师诞辰。家家檐下挂灯，十几个门派来客，供桌上的供品比人还高。你被分派了一份差事。`),
 opts:[{l:T('Usher the guests','迎宾'),out:[{w:2,t:T('You bow four hundred times. A famous swordsman remembers your name, or says he does.','你鞠了四百个躬。一位成名剑客说他记住了你的名字——至少他是这么说的。'),c:'good',fx:{merit:3,fame:1,meet:'acq',bond:50}},{w:1,t:T('You seat two sects that hate each other at the same table. Somehow it ends in a drinking contest instead of a fight.','你把两个互相仇视的门派安排到了一桌。不知怎的，最后变成了拼酒而不是打架。'),fx:{merit:1,happy:4}}]},
  {l:T('Perform the sword dance','献演剑舞'),out:[{w:s=>1+power(s)/50,t:T('The courtyard falls silent, then roars. The master’s beard twitches, which is the highest praise there is.','满院先是一静，随即喝彩如雷。师父的胡子抖了一抖——这是最高的夸奖了。'),c:'gold',fx:{merit:5,fame:3}},{w:1,t:T('Your sword tassel catches a lantern. The fire is put out quickly. The story lasts for years.','你的剑穗勾着了灯笼。火很快就灭了，这段笑话却流传了好多年。'),c:'bad',fx:{merit:-1,happy:-3}}]},
  {l:T('Help in the kitchens','去伙房帮忙'),out:[{t:T('You fold nine hundred dumplings and eat about forty. The cooks adopt you.','你包了九百个饺子，偷吃了四十来个。伙房上下都认你做自己人了。'),c:'good',fx:{merit:3,happy:3}}]}]});

I({id:'sc_bigcontest',age:[13,45],tags:CH,only:1,cd:3,w:1.3,when:scOK,ctx:scCtx({}),
 text:(c,s)=>T(`The great contest of ${SECTS[s.sect].en} (门派大比) is held in the main yard. Your name is drawn against your ${c.sib.en}, ${c.npc.en}. The whole sect sits on the steps to watch.`,`${SZ(s.sect)}门派大比在大校场举行。你抽中的对手是${c.sib.zh}${c.npc.zh}。全派的人都坐在台阶上看着。`),
 opts:[{l:T('Fight your best','全力以赴'),fight:FG((s,c)=>c.npc.lv,'spar',T('The sect contest','门派大比'),T('a sect contest','门派比武')),
   win:[{w:2,t:T('You win cleanly and bow. The elders write something in their book. You hope it is your name.','你干净利落地赢了，躬身行礼。长老们在册子上记了一笔，你希望记的是你的名字。'),c:'good',fx:{merit:6,fame:2}},{w:1,t:T('You win, and help your opponent up. The master nods at that more than at the win.','你赢了，又伸手把对手拉了起来。师父对这一下点头，比对你赢了还满意。'),c:'good',fx:{merit:6,align:2,bond:3}}],
   lose:[{t:T('You lose, but you lasted longer than anyone expected. A few elders exchange looks.','你输了，但撑得比所有人预料的都久。几位长老交换了一下眼色。'),c:'muted',fx:{merit:2,skill:1}}]},
  {l:T('Let them win quietly','暗中相让'),out:[{w:1,t:c=>T(`${c.npc.en} wins and never knows. Later they get you the best seat at the feast.`,`${c.npc.zh}赢了，始终不知道。后来宴席上，对方把最好的位子让给了你。`),c:'muted',fx:{merit:1,meet:'friend',bond:62}},{w:1,t:T('The master saw exactly what you did. "Never insult an opponent like that again."','师父看得一清二楚。"以后不准再这样羞辱对手。"'),c:'bad',fx:{merit:-2}}]}]});

I({id:'sc_finals',age:[16,45],tags:CH,only:1,cd:8,when:s=>scOK(s)&&power(s)>=25,ctx:s=>{const c=scene();return scFellow(s,c,{fresh:1,age:clamp(s.age+rint(2,8),16,60),lv:Math.round(power(s)*1.1+rint(2,8))})},
 text:c=>T(`You reach the last round of the sect contest. Across the yard stands ${c.npc.en}, the sect’s pride, who has not lost in six years. People are betting on how long you will last.`,`你闯进了门派大比的最后一轮。对面站着的是本门的骄傲${c.npc.zh}，六年没输过。台下有人在赌你能撑几招。`),
 opts:[{l:T('Go for the win','拼一把'),fight:FG((s,c)=>c.npc.lv,'light',T('The final round','大比决战'),T('the final of a sect contest','门派大比决战')),
   win:[{t:T('Six years ends with you. The sect is too stunned to cheer, and then it cheers for an hour.','六年的不败断在你手里。全场先是愣住，然后欢呼了足足一个时辰。'),c:'gold',fx:{merit:10,fame:5,deed:T('Won the great contest of the sect','夺得门派大比魁首')}}],
   lose:[{w:2,t:T('You last forty moves. Nobody bet on forty. The winner tells the elders to watch you.','你撑了四十招。没人押四十招。赢家对长老们说：这个人要留意。'),c:'good',fx:{merit:4,fame:1}},{w:1,t:T('A cracked rib and a lesson about pride.','断了一根肋骨，学到一课：不能太傲。'),c:'bad',fx:{merit:2,hurt:[4,10],cause:T('a sect contest','门派比武')}}]},
  {l:T('Bow out with grace','拱手认输'),out:[{t:c=>T('"Senior, I have learned enough watching you." The crowd groans. The champion smiles, and later teaches you one of their moves.',`"${c.sib.zh}的功夫，我看着就学到了。"台下一阵叹气。那位魁首却笑了，后来还教了你一招。`),c:'muted',fx:{merit:2,skill:2,meet:'friend',bond:58}}]}]});

I({id:'sc_lostmanual',age:[13,60],tags:CH,only:1,cd:12,when:scOK,ctx:scCtx({}),
 text:(c,s)=>T(`A manual has vanished from the locked chest where ${SECTS[s.sect].en} keeps its manuals. The gates are shut and every room is searched. You notice ${c.sib.en} ${c.npc.en} has been very nervous all morning.`,`${SZ(s.sect)}锁在箱里的一本秘籍不见了。山门紧闭，挨屋搜查。你注意到${c.sib.zh}${c.npc.zh}一上午都坐立不安。`),
 opts:[{l:T('Quietly ask them about it','私下问问对方'),out:[{w:2,t:c=>T(`${c.npc.en} confesses: they borrowed it to copy one page, panicked, and hid it in a drain. You return it together at night. Nobody else ever knows.`,`${c.npc.zh}招了：只是借来抄一页，一慌就塞进了水沟。你们夜里一起把它放了回去，再没第三个人知道。`),c:'good',fx:{merit:2,meet:'friend',bond:70}},{w:1,t:c=>T(`${c.npc.en} is nervous because of a secret sweetheart, nothing more. The real thief is a cook’s boy, caught at the gate.`,`${c.npc.zh}心虚，不过是因为偷偷有了意中人。真正的贼是伙房的小杂役，在山门口被抓住了。`),fx:{happy:2,merit:1}}]},
  {l:T('Report your suspicion','把怀疑报上去'),out:[{w:1,t:T('They are searched and the manual is found. The elders praise you. Your fellows stop talking when you enter rooms.','一搜就搜出来了。长老们夸了你。从此你一进屋，同门们就不说话了。'),c:'muted',fx:{merit:5,enemy:1}},{w:1,t:T('They are searched and nothing is found. You have made an enemy over nothing.','搜了，什么也没有。你平白结了个仇。'),c:'bad',fx:{merit:-2,enemy:1}}]},
  {l:T('Search the grounds yourself at night','夜里自己去查'),out:[{w:s=>s.smarts/30,t:T('Footprints on the roof lead to an outsider’s rope. The manual is under a loose tile, waiting to be collected. You wait instead.','藏经阁屋顶上的脚印通向一根外人的绳索。秘籍压在一块松动的瓦片下，等人来取。你守在那里，等到了来人。'),c:'gold',fx:{merit:8,fame:2}},{w:1,t:T('You find nothing but a nest of owls and a cold.','你只找到一窝猫头鹰，还着了凉。'),fx:{ill:'cold'}}]}]});

I({id:'sc_gateguest',age:[13,70],tags:CH,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([7,19,13,24]),age:rint(50,80),lv:rint(80,200)});return c},
 text:c=>T(`On gate duty, a ragged old traveller, ${c.npc.en}, asks to see the sect master. "Tell him the one who still owes him a game of chess is here."`,`你守山门时，来了个衣衫褴褛的老人${c.npc.zh}，说要见掌门。"就说欠他一盘棋的人来了。"`),
 opts:[{l:T('Announce him properly','恭恭敬敬去通报'),out:[{w:2,t:T('The sect master comes running down the steps in slippers. The game lasts three days. On the way out, the old man taps your shoulder, and your arm tingles for a week.','掌门趿着鞋从台阶上跑下来。那盘棋下了三天。临走时老人拍了拍你的肩，你的胳膊麻了一个星期。'),c:'gold',fx:{merit:3,qi:5}},{w:1,t:T('He is a con man who eats three meals and steals a teapot. The master laughs and says he does that every ten years.','原来是个骗子，吃了三顿饭，顺走了一把茶壶。掌门哈哈大笑，说他每十年都来这么一回。'),fx:{merit:2,happy:3}}]},
  {l:T('Turn him away','把他打发走'),out:[{w:1,t:T('Months later you learn he was the sect master’s sworn brother. Nobody tells you off. That is worse.','几个月后你才知道，那是掌门的结义兄弟。没人骂你。这才更难受。'),c:'bad',fx:{merit:-2,happy:-2}},{w:1,t:T('He shrugs and climbs the cliff instead, in ten breaths, without hands.','他耸耸肩，转身攀上了悬崖——十口气的工夫，没用手。'),c:'muted',fx:{smarts:1}}]},
  {l:T('Test him first','先试他一试'),fight:FG((s,c)=>c.npc.lv,'spar',T('A test at the gate','山门试招'),T('an old man at the gate','山门前的老人')),win:[{t:T('You win. He laughs, slips past you anyway, and you realise he let you.','你赢了。他大笑着从你身边闪了过去——你这才明白是他让着你。'),c:'muted',fx:{skill:2}}],lose:[{t:T('He knocks you down with a sleeve and steps over you. "Good stance. Bad manners."','他袖子一拂就把你放倒了，跨过你走了进去。"架势不错，礼数太差。"'),fx:{skill:1,merit:1}}]}]});

I({id:'sc_admirer',age:[16,60],tags:CH,only:1,cd:12,when:scOK,ctx:s=>{const c=scene();return scFellow(s,c,{fresh:1,age:clamp(s.age-rint(3,8),10,50),lv:Math.max(2,Math.round(power(s)*.5))})},
 text:c=>T(`A young ${c.sib.en}, ${c.npc.en}, has started copying everything you do: your walk, the way you hold your cup, even your cough.`,`年幼的${c.sib.zh}${c.npc.zh}开始什么都学你：走路的样子，端茶的姿势，连咳嗽都学。`),
 opts:[{l:T('Take them under your wing','带一带这孩子'),out:[{w:3,t:c=>T(`You show ${c.npc.en} the basics properly. They improve fast, and tell everyone who taught them.`,`你一板一眼地教${c.npc.zh}基本功。孩子进步很快，逢人便说是谁教的。`),c:'good',fx:{merit:4,fame:1,meet:'friend',bond:75}},{w:1,t:T('They copy your bad habits too, perfectly. The master looks at the two of you and sighs.','你的坏毛病他们也学了个十足。师父看着你们俩，叹了口气。'),fx:{merit:2,happy:3,meet:'friend',bond:70}}]},
  {l:T('Tell them to find their own way','叫对方走自己的路'),out:[{t:T('They are hurt, then thoughtful. Years later they thank you for it.','孩子先是难过，后来若有所思。多年后专门来谢你这句话。'),c:'muted',fx:{merit:1,smarts:1}}]},
  {l:T('Enjoy it shamelessly','心安理得地享受'),out:[{t:T('Your laundry gets done for a year. Your pride grows a little too large for your robes.','这一年你的衣服都有人洗了。你的得意也快撑破道袍了。'),fx:{happy:5,align:-1}}]}]});

I({id:'sc_framed',age:[14,55],tags:CH,only:1,cd:15,when:scOK,ctx:scCtx({fresh:1}),
 text:c=>T(`The elixir furnace has been opened and three pills are missing. A witness swears they saw you near it at midnight. It was ${c.npc.en} who said so, and you know where you really were.`,`丹房的炉子被人打开，少了三颗丹药。有人发誓半夜看见你在炉边。说这话的是${c.npc.zh}，而你很清楚自己那时在哪儿。`),
 opts:[{l:T('Find the real thief','找出真贼'),out:[{w:s=>s.smarts/25+s.t.wit/5,t:c=>T(`Pill wax on ${c.npc.en}’s sleeve. ${c.npc.He} confesses in front of the hall, and you are cleared with an apology from the elders.`,`${c.npc.zh}袖口沾着丹蜡。${c.npc.ta}在大殿上认了罪，长老们当众向你赔了不是。`),c:'good',fx:{merit:6,enemy:1}},{w:1,t:T('You get close, but not close enough. The matter is dropped, and a cloud hangs over your name.','你查到了边上，却差了一步。此事不了了之，你的名声上蒙了一层灰。'),c:'muted',fx:{merit:-2}}]},
  {l:T('Accept the punishment to keep the peace','认罚，息事宁人'),out:[{w:1,t:T('Thirty strokes and a month in the woodshed. The next spring, the witness quietly leaves the sect, and the master gives you a look that says he knows.','三十板，柴房关了一个月。来年春天，那个作证的人悄悄离开了师门。师父看你的眼神，分明什么都知道。'),c:'muted',fx:{merit:3,hurt:[3,8],cause:T('a sect flogging','门规杖责'),bond:6,align:2}}]},
  {l:T('Challenge the accuser','向诬告者下战书'),fight:FG((s,c)=>c.npc.lv,'light',T('Clearing your name','以武证清白'),T('a quarrel over stolen pills','丹药失窃之争')),
   win:[{t:T('You win, and in the dust they blurt the truth. It is not how the rules say justice works, but it works.','你赢了。对方在尘土里脱口说出了真相。门规上的公道不是这么讨的，可这回讨到了。'),c:'good',fx:{merit:2,fame:1,enemy:1}}],
   lose:[{t:T('You lose, and now you look guilty and beaten. A bad month.','你输了，如今既像贼又挨了打。好一个倒霉的月份。'),c:'bad',fx:{merit:-3,happy:-4}}]}]});

I({id:'sc_nightsword',age:[12,45],tags:CH,only:1,cd:10,when:scOK,ctx:scMctx,
 text:()=>T('You have been sneaking to the back hill every night to practise a move you are not supposed to learn yet.','你每晚都溜到后山，偷练一招按规矩还轮不到你学的功夫。'),
 opts:[{l:T('Keep at it','接着练'),out:[{w:2,t:T('One night it clicks. You stand in the moonlight with your heart pounding, and nobody in the world knows.','有天夜里，忽然通了。你站在月光下，心跳如鼓，天下没有一个人知道。'),c:'gold',fx:{skill:4,qi:2}},{w:1,t:T('Your master steps out of the trees. "Your wrist is wrong. Like this." Then leaves without another word.','师父从树后走了出来。"手腕不对，要这样。"说完一个字也没再说就走了。'),c:'good',fx:{skill:3,bond:6,merit:1}},{w:1,t:T('You get the breathing wrong and cough blood for a week.','你的呼吸走岔了，咳了一个星期的血。'),c:'bad',fx:{hurt:[5,12],cause:T('qi deviation','练功走火')}}]},
  {l:T('Confess and ask to learn it properly','坦白，请求正式传授'),out:[{w:1,t:T('"Too early." But from then on your lessons are a little harder, and a little more interesting.','"还早。"可从那以后，你的功课难了一点，也有意思了一点。'),c:'good',fx:{bond:5,merit:3,skill:1}},{w:1,t:T('You are told to sweep the back hill every morning. The very hill. The master has a sense of humour.','罚你每天早上去扫后山——就是那座山。师父也是有幽默感的。'),c:'muted',fx:{merit:2,happy:-1}}]}]});

I({id:'sc_spiritherb',age:[11,50],tags:CH,only:1,cd:10,when:scOK,ctx:scCtx({}),
 text:c=>T(`You tend the sect’s herb garden. This morning the elder’s prize spirit herb, sixty years in the growing, is gone. ${c.sib.en} ${c.npc.en} is sitting behind the shed, glowing faintly.`,`你在门中药圃当差。今早长老那株养了六十年的灵草不见了。${c.sib.zh}${c.npc.zh}正坐在棚子后头，身上微微发光。`),
 opts:[{l:T('Cover for them','替对方遮掩'),out:[{w:2,t:T('You blame a deer. The elder roars for a day, then plants another. Your fellow owes you for life, and their inner energy is now terrifying.','你说是鹿啃的。长老怒吼了一天，又种上了一株。对方欠了你一辈子的情，内力也从此吓人。'),c:'good',fx:{meet:'friend',bond:75,align:-1}},{w:1,t:T('There are no deer on this mountain. You both scrub the latrines for a season.','这座山上压根没有鹿。你们俩一起刷了一季茅房。'),c:'bad',fx:{merit:-2,meet:'friend',bond:70}}]},
  {l:T('Bring them to the elder','把对方带去见长老'),out:[{t:T('The elder is furious, then curious: the herb was meant to be eaten by someone. He takes your fellow as a personal disciple. You get a thank-you and a hoe.','长老先是暴怒，后又好奇：灵草本来就是要给人吃的。他把对方收作了亲传弟子。你得了一声谢，还有一把锄头。'),c:'muted',fx:{merit:4}}]},
  {l:T('Ask what it tasted like','问问是什么味道'),out:[{t:T('"Like a summer storm." They give you the last leaf. You do not glow, but you sleep beautifully.','"像夏天的暴雨。"对方把最后一片叶子给了你。你没发光，但睡得特别香。'),c:'good',fx:{qi:3,heal:10}}]}]});

I({id:'sc_fever',age:[11,60],tags:CH,only:1,cd:12,when:scOK,ctx:scCtx({}),
 text:c=>T(`A fever sweeps through the disciples’ quarters. ${c.sib.en} ${c.npc.en} is the worst hit, burning and calling for their mother.`,`一场热病在弟子房里蔓延开来。${c.sib.zh}${c.npc.zh}病得最重，烧得说胡话，一直喊娘。`),
 opts:[{l:T('Nurse them through the nights','守着对方熬过去'),out:[{w:3,t:T('Seven nights of cold cloths and bitter soup. They live. They never forget who sat there.','七个晚上的冷帕子和苦药汤。对方挺了过来，永远记得是谁守在床边。'),c:'good',fx:{merit:4,align:2,meet:'friend',bond:80}},{w:1,t:T('They live, and you catch it next.','对方好了，你接着病倒了。'),c:'muted',fx:{merit:3,meet:'friend',bond:75,ill:'fever'}}]},
  {l:T('Stay away from the sickroom','远离病房'),out:[{t:T('You stay healthy. It is a long, quiet month.','你没被传上。那是漫长又安静的一个月。'),c:'muted'}]},
  {l:T('Climb for the herb the old books mention','去采古书上记载的草药'),out:[{w:2,t:T('You find it on a cliff ledge at dawn, and the fever breaks across the whole quarter in two days.','天亮时你在崖边找到了它。两天后，整排弟子房的热都退了。'),c:'gold',fx:{merit:7,fame:1,meet:'friend',bond:75}},{w:1,t:T('The ledge gives way. You come back without the herb, with a limp.','崖边的石头塌了。你空手而回，还瘸了腿。'),c:'bad',fx:{hurt:[6,14],cause:T('a fall from a cliff','坠崖')}}]}]});

I({id:'sc_debt',age:[15,50],tags:CH,only:1,cd:12,when:scOK,ctx:scCtx({}),
 text:c=>T(`${c.sib.en} ${c.npc.en} has run up gambling debts in town. If the sect finds out, it is expulsion. ${c.npc.He} asks you for 40 taels.`,`${c.sib.zh}${c.npc.zh}在镇上欠了赌债。要是让师门知道，就是逐出门墙。${c.npc.ta}找你借四十两。`),
 opts:[{l:T('Pay it','替对方还上'),cost:40,out:[{w:2,t:T('They swear never to gamble again, and almost mean it. The silver comes back, slowly, in odd coins.','对方发誓再也不赌了，也差不多是真心的。银子后来零零碎碎地还回来了。'),c:'good',fx:{money:25,meet:'friend',bond:70}},{w:1,t:T('They swear never to gamble again. Next month the debt is twice as large.','对方发誓再也不赌了。下个月债翻了一倍。'),c:'bad',fx:{happy:-3}}]},
  {l:T('Go and talk to the gambling den','去赌坊讲讲道理'),fight:FG(PW(.9,3),'light',T('The gambling den','赌坊'),T('a gambling den brawl','赌坊斗殴'),()=>T('the den’s bouncer','赌坊打手')),
   win:[{t:T('The debt is "forgiven". So is the den, barely. Word reaches the sect, and the master pretends to be angry.','债"一笔勾销"了，赌坊也差点被你拆了。消息传回山上，师父装作很生气。'),c:'good',fx:{merit:1,fame:1,meet:'friend',bond:70}}],
   lose:[{t:T('Now there are two of you who owe the den.','现在欠赌坊钱的变成了两个人。'),c:'bad',fx:{money:-20,happy:-3}}]},
  {l:T('Tell them to confess','叫对方去自首'),out:[{w:1,t:T('They confess. The master is harsh but fair, and they are not expelled. They are grateful, eventually.','对方认了。师父罚得狠，但没逐出门墙。对方后来也感激你。'),c:'muted',fx:{merit:2,align:2}},{w:1,t:T('They run away instead. You never see them again.','对方连夜跑了。你再也没见过。'),c:'bad',fx:{happy:-3}}]}]});

I({id:'sc_homeletter',age:[12,40],tags:CH,only:1,cd:12,when:s=>scOK(s)&&living(s,['father','mother']).length>0,
 text:()=>T('A letter from home: the harvest failed, and your family is struggling. Leaving the mountain without permission is forbidden.','家里来信：今年收成不好，日子很难熬。未经允许私自下山是犯门规的。'),
 opts:[{l:T('Ask the master for leave','向师父告假'),out:[{w:2,t:T('Permission, and a purse from the sect’s charity fund. Your mother cries at the door.','师父准了，还从门中善款里拨了一袋银子。母亲在门口哭了。'),c:'good',fx:{merit:1,happy:5,money:-10}},{w:1,t:T('Permission, but only for a week. You run most of the way.','准了，可只有七天。你大半路是跑着去的。'),fx:{happy:3,skill:1}}]},
  {l:T('Send your savings home','把积蓄寄回家'),cost:30,out:[{t:T('Your family eats through the winter. You eat a little less.','家里人熬过了冬天。你自己吃得少了些。'),c:'good',fx:{align:2,happy:2}}]},
  {l:T('Slip away at night','夜里偷偷下山'),out:[{w:1,t:T('You fix the roof and plant the next crop, and come back to find a month of chores waiting.','你修了屋顶，种下了来年的庄稼。回山时，一个月的杂役等着你。'),c:'muted',fx:{merit:-3,happy:4}},{w:1,t:T('Nobody notices you were gone. The sect is bigger than you thought.','没人发觉你走过。门派比你以为的大。'),fx:{happy:3}}]}]});

I({id:'sc_lecture',age:[11,40],tags:CH,only:1,cd:6,when:scOK,
 text:()=>T('The eldest elder’s lecture on the sect rules enters its third hour. Your eyelids weigh more than the bronze bell.','大长老讲门规已经讲到第三个时辰了。你的眼皮比铜钟还沉。'),
 opts:[{l:T('Ask a sharp question','提一个尖锐的问题'),out:[{w:s=>s.smarts/30,t:T('The elder stops, thinks, and says, "Good." He talks to you for another hour, privately. It is the most useful hour of your year.','长老顿住，想了想，说："问得好。"又单独跟你讲了一个时辰，那是你这一年最有用的一个时辰。'),c:'good',fx:{smarts:3,merit:3}},{w:1,t:T('He answers for two more hours. The other disciples will not forgive you.','他又答了两个时辰。同门们不会原谅你的。'),fx:{merit:1,happy:-2}}]},
  {l:T('Doze with your eyes open','睁着眼打盹'),out:[{w:2,t:T('A skill every disciple learns sooner or later. You learn it today.','每个弟子迟早要学会的本事，你今天学会了。'),fx:{happy:2}},{w:1,t:T('You snore. Rule forty-one, it turns out, is about snoring.','你打呼噜了。原来第四十一条门规就是讲打呼噜的。'),c:'bad',fx:{merit:-1}}]},
  {l:T('Actually listen','真的认真听'),out:[{t:T('Buried in the rules is the story of why each one was made. Most were made because someone died.','每条门规背后都有它的来历，大多是因为有人死了。'),c:'muted',fx:{align:2,merit:2,smarts:1}}]}]});

I({id:'sc_latereturn',age:[14,50],tags:CH,only:1,cd:10,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(55,75),lv:rint(90,160)});return c},
 text:c=>T(`At the third watch, Elder ${c.npc.en} climbs over the wall smelling of plum wine, and finds you on guard. "You saw nothing," he whispers, "and I will remember it."`,`三更天，${c.npc.zh}长老一身梅子酒味翻墙进来，正撞见你在值夜。"你什么都没看见，"他压低声音，"我记你一个人情。"`),
 opts:[{l:T('See nothing','什么也没看见'),out:[{w:2,t:T('He does remember. Next month he "happens" to teach you a breathing trick in the corridor.','他真记得。下个月他在回廊里"顺便"教了你一手吐纳的诀窍。'),c:'good',fx:{qi:4,meet:'acq',bond:60}},{w:1,t:T('He forgets entirely, which is the danger with plum wine.','他忘得一干二净——梅子酒的坏处就在这儿。'),c:'muted'}]},
  {l:T('Log it, as the rules say','按规矩记下来'),out:[{t:T('The elder is fined a month’s wine. He is cold to you for years, but the master trusts you with the night keys after that.','长老被罚停酒一个月。他冷了你好些年，但此后师父把夜钥交给了你。'),c:'muted',fx:{merit:4,align:1}}]},
  {l:T('Ask him to share','请他分一口'),out:[{t:T('You both sit on the wall and finish the jar. It is the best night of the year, and the worst morning.','你们俩坐在墙头把一坛酒喝光了。这是一年里最好的夜晚，也是最难受的早晨。'),fx:{happy:5,merit:-1,meet:'friend',bond:60}}]}]});

I({id:'sc_choosekids',age:[20,70],tags:CH,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([20,21]),age:rint(8,11),lv:2});return c},
 text:(c,s)=>T(`On the day ${SECTS[s.sect].en} takes in new disciples, you test the children at the gate. One, ${c.npc.en}, is thin and barefoot and fails every test, but will not stop getting up.`,`${SZ(s.sect)}收徒那天，你在山门口考校孩子们。有个叫${c.npc.zh}的，又瘦又光着脚，每一关都没过，可一次次又爬起来。`),
 opts:[{l:T('Speak up for the child','替孩子说情'),out:[{w:2,t:c=>T(`The elders let ${c.npc.en} in on trial. ${c.npc.He} brings you wild berries every week for years.`,`长老们让${c.npc.zh}留下试试。此后好几年，${c.npc.ta}每个星期都给你送野果子。`),c:'good',fx:{merit:3,align:3,meet:'friend',bond:70}},{w:1,t:T('The elders refuse. You give the child your dinner and the address of a kind blacksmith.','长老们没答应。你把晚饭给了孩子，又告诉他一个好心铁匠的住处。'),c:'muted',fx:{align:2}}]},
  {l:T('Follow the rules','按规矩办'),out:[{t:T('The child walks back down the mountain. You think about it more than you expected.','孩子走下了山。你比自己预料的想得更多。'),c:'muted',fx:{merit:2,happy:-1}}]}]});

I({id:'sc_relicsword',age:[12,45],tags:CH,only:1,cd:20,when:scOK,
 text:(c,s)=>T(`In practice you borrow a sword from the rack and it snaps in two. It is not a practice sword. It is the founder of ${SECTS[s.sect].en}’s own sword, put on the wrong rack by someone.`,`练剑时你从架上随手取了一把剑，一用力就断成了两截。那不是练习剑，是${SZ(s.sect)}祖师爷的佩剑，不知被谁放错了架子。`),
 opts:[{l:T('Confess at once','立刻认错'),out:[{w:2,t:T('The master is silent a long while. Then: "He broke three swords himself. He would laugh." You copy the founder’s sayings a hundred times anyway.','师父沉默良久，说："祖师爷自己就折过三把剑，他会笑的。"不过你还是被罚把祖师语录抄了一百遍。'),c:'muted',fx:{merit:1,align:2,smarts:2}},{w:1,t:T('You are made to kneel before the ancestral tablets for three days. Your knees remember it longer than you do.','你被罚在祖师牌位前跪了三天。你的膝盖比你记得还久。'),c:'bad',fx:{merit:-2,hurt:[2,5],cause:T('kneeling three days','跪了三天')}}]},
  {l:T('Take it to a master smith in secret','偷偷拿去找铸剑名匠'),cost:60,out:[{w:2,t:T('Sixty taels and a week later, it is whole again. The smith says the old steel was badly made. You keep that to yourself.','六十两银子、一个星期，剑接好了。匠人说那老钢本就炼得不好。这话你烂在了肚子里。'),fx:{smarts:1}},{w:1,t:T('The smith recognises the sword and sends word to the sect. Now it is a broken sword and a lie.','匠人认得这把剑，派人报了师门。这下既断了剑，又撒了谎。'),c:'bad',fx:{merit:-4}}]}]});

I({id:'sc_accounts',age:[18,65],tags:CH,only:1,cd:15,when:s=>scOK(s)&&s.smarts>=35,ctx:s=>{const c=scene();c.npc=npc(s,{occ:26,age:rint(40,60),lv:Math.round(power(s)*.8)});return c},
 text:c=>T(`Asked to help with the sect’s ledgers, you find that the steward, ${c.npc.en}, has been skimming rice money for years.`,`你被叫去帮着对门中的账，发现管事${c.npc.zh}这些年一直在克扣米钱。`),
 opts:[{l:T('Take it to the elders','报给长老'),out:[{w:2,t:T('The steward is expelled. The elders give you the ledgers to keep from now on, which is an honour and a headache.','管事被逐出师门。长老们从此把账本交给你管，这是体面，也是头疼。'),c:'good',fx:{merit:8,align:2,enemy:1}},{w:1,t:T('The steward is an elder’s cousin. Nothing happens, except that your chores get much worse.','管事是某位长老的表亲。什么也没发生，只是你的差事变得难多了。'),c:'bad',fx:{merit:-2,enemy:1}}]},
  {l:T('Make him pay it back quietly','让他悄悄补上'),out:[{t:T('He pays it back over a year, with interest, and calls you "young sir" from then on.','他用一年连本带利地补上了，此后见了你就叫"小爷"。'),c:'muted',fx:{merit:3,meet:'acq',bond:40}}]},
  {l:T('Ask for a share','要一份好处'),out:[{w:1,t:T('Twenty taels a season. You sleep worse than you used to.','每季二十两。你睡得没以前踏实了。'),c:'bad',fx:{money:40,align:-4}},{w:1,t:T('It all comes out a year later, and your name is in the ledger too.','一年后东窗事发，账本上也有你的名字。'),c:'bad',fx:{money:20,align:-4,merit:-8}}]}]});

I({id:'sc_rivalguests',age:[14,55],tags:CH,only:1,cd:10,when:scOK,ctx:s=>{const c=scene();const ks=Object.keys(SECTS).filter(k=>k!==s.sect&&!SECTS[k].hidden&&!SECTS[k].female);c.o=pick(ks);c.npc=npc(s,{occ:13,age:clamp(s.age+rint(-2,4),15,60),lv:Math.round(power(s)*rint(9,11)/10)});return c},
 text:c=>T(`Disciples of ${SE(c.o)} are visiting. At tea, their loudest, ${c.npc.en}, says your sect’s arts are "pretty, for a dance".`,`${SZ(c.o)}的弟子来访。喝茶时，他们中嗓门最大的${c.npc.zh}说你们门派的武功"跳舞倒挺好看"。`),
 opts:[{l:T('Invite them to the yard','请到校场一叙'),fight:FG((s,c)=>c.npc.lv,'spar',T('A friendly exchange','以武会友'),T('a friendly exchange','以武会友')),
   win:[{t:T('You win in a dozen moves. They bow and admit it was a good dance. You become pen friends.','十几招你就赢了。对方拱手认了，说"这舞跳得好"。你们后来成了笔友。'),c:'good',fx:{merit:4,fame:2,meet:'friend',bond:55}}],
   lose:[{t:T('You lose. Your elders’ faces are very still. Extra practice for a month.','你输了。长老们的脸一动不动。加练一个月。'),c:'bad',fx:{merit:-1,skill:1}}]},
  {l:T('Answer with a joke','用一句玩笑回敬'),out:[{w:s=>s.smarts/30,t:T('"Then come and dance with us." The table laughs, the tension breaks, and the guests leave as friends.','"那就请下场一起跳。"满桌哄笑，剑拔弩张一下子化开了，客人们走时成了朋友。'),c:'good',fx:{merit:3,fame:1}},{w:1,t:T('The joke lands badly. Their master has to apologise to yours.','玩笑没接住。对方师父只好向你师父赔了不是。'),fx:{merit:1}}]},
  {l:T('Smile and pour more tea','笑笑，再添茶'),out:[{t:T('Your master sees, and nods. Restraint is also an art.','师父看在眼里，点了点头。忍，也是一门功夫。'),c:'muted',fx:{merit:2,qi:1}}]}]});

I({id:'sc_monkey',age:[11,50],tags:CH,only:1,cd:10,when:scOK,
 text:()=>T('A monkey has been stealing the fruit offerings from the main hall. The elders blame the disciples. You are told to catch it.','有只猴子一直在偷大殿上的供果。长老们怪到了弟子头上，派你去抓。'),
 opts:[{l:T('Chase it through the trees','上树去追'),out:[{w:2,t:T('Three days of chasing improves your light-body skill more than a year of drills. You never catch it.','追了三天，你的轻功长进比练一年还多。猴子终究没抓着。'),c:'good',fx:{skill:2,merit:2}},{w:1,t:T('You catch it. It bites you, then sits on your shoulder for the rest of the year.','你抓住了。它咬了你一口，然后这一年都蹲在你肩膀上。'),c:'good',fx:{merit:3,happy:4}}]},
  {l:T('Set out wine as a trap','摆一碗酒做诱饵'),out:[{t:T('The monkey drinks, dances, and falls asleep on the altar. So does the elder who came to check.','猴子喝了，跳了一阵舞，在供桌上睡着了。来查看的长老也是。'),fx:{merit:3,happy:5}}]},
  {l:T('Leave it some fruit of its own','另外给它留些果子'),out:[{t:T('The thefts stop. The monkey leaves you a pine cone every morning. You decide this is friendship.','偷窃停了。猴子每天早上给你留一颗松果。你认定这算是交情。'),c:'good',fx:{merit:2,align:1,happy:3}}]}]});

I({id:'sc_bruised',age:[13,45],tags:CH,only:1,cd:10,when:scOK,ctx:scCtx({}),
 text:c=>T(`In sparring practice, you strike harder than you meant to. ${c.sib.en} ${c.npc.en} goes down and does not get up for a long, frightening moment.`,`对练时你下手重了。${c.sib.zh}${c.npc.zh}倒在地上，好半天没起来，吓得人心慌。`),
 opts:[{l:T('Carry them to the infirmary','背去药庐'),out:[{w:2,t:T('A cracked collarbone. You bring meals every day until it heals, and something like trust grows out of it.','锁骨裂了。你每天送饭，直到伤好。一来二去，倒生出了几分信任。'),c:'good',fx:{merit:2,meet:'friend',bond:65}},{w:1,t:T('They recover, but flinch whenever you raise your hand. You practise control for a year.','对方好了，可你一抬手就往后缩。你苦练了一年收发自如。'),c:'muted',fx:{qi:3,skill:1}}]},
  {l:T('Report yourself to the master','向师父请罪'),out:[{t:T('"A strong hand is useless without a gentle one." You are set to practise stopping a blade a hair from a rice paper sheet. For months.','"重手无用，须能收住。"师父叫你练剑尖停在宣纸前一丝的地方，一练就是几个月。'),c:'good',fx:{merit:3,skill:2,qi:1}}]}]});

I({id:'sc_gossip',age:[14,50],tags:CH,only:1,cd:10,when:s=>scOK(s)&&!!masterOf(s),ctx:scCtx({}),
 text:c=>T(`The whole sect is whispering that your master favours ${c.sib.en} ${c.npc.en}, and will teach them the secret art first.`,`全派都在私下传，说师父偏心${c.sib.zh}${c.npc.zh}，绝学要先传给对方。`),
 opts:[{l:T('Ignore it','不理会'),out:[{w:2,t:T('You go on practising. The rumour dies, as rumours do, and the master notices who never joined in.','你照常练功。谣言自己散了，谣言向来如此。师父记住了谁从没掺和过。'),c:'good',fx:{merit:3,qi:2}},{w:1,t:T('It turns out to be true. You swallow it, and practise harder.','后来证明这是真的。你把这口气咽了下去，练得更狠了。'),c:'muted',fx:{skill:2,happy:-2}}]},
  {l:T('Confront the favourite','找对方当面说'),out:[{w:1,t:T('They are as miserable about the rumour as you are. You end up drinking together.','对方被这谣言折磨得跟你一样苦。最后你们一起喝起了酒。'),c:'good',fx:{meet:'friend',bond:60}},{w:1,t:T('It turns into shouting, then a scuffle. Both of you face the wall.','说着说着就吵了起来，接着动了手。两个人一起面壁。'),c:'bad',fx:{merit:-2,meet:'rival',bond:25}}]},
  {l:T('Work to outshine them','暗暗较劲'),out:[{t:T('A year of dawn practice. Whether or not the rumour was true, you are better than you were.','一年的闻鸡起舞。不管谣言是真是假，你确实比以前强了。'),c:'good',fx:{skill:3,merit:2}}]}]});

I({id:'sc_furnace',age:[14,60],tags:CH,only:1,cd:12,when:scOK,
 text:()=>T('You are assigned to watch the elixir furnace for forty-nine days: keep the fire exactly so, day and night, and never let it go out.','你被派去看守丹炉四十九天：日夜看火，火候分毫不差，绝不能熄。'),
 opts:[{l:T('Do it perfectly','一丝不苟'),out:[{w:2,t:T('On the forty-ninth day the lid lifts and the hall smells of rain and pine. The elder gives you one of the pills.','第四十九天开炉，满屋都是雨后松林的气味。长老赏了你一颗丹药。'),c:'gold',fx:{merit:6,qi:5,heal:15}},{w:1,t:T('You do everything right and the batch fails anyway. "That is alchemy," says the elder, cheerfully.','你样样做对了，那一炉还是废了。"炼丹就是这样，"长老倒是很开心。'),c:'muted',fx:{merit:4}}]},
  {l:T('Use the time to meditate','趁机打坐'),out:[{w:2,t:T('The fire and your breath fall into the same rhythm. You come out with stronger inner energy and a beautiful batch.','炉火和你的呼吸合上了同一个节拍。出关时内力更深，那炉丹也成色极好。'),c:'good',fx:{merit:4,qi:5}},{w:1,t:T('You drift off. The fire drops. The batch becomes forty-nine days of expensive charcoal.','你神游太虚，火候一落，四十九天的心血变成了一炉昂贵的木炭。'),c:'bad',fx:{merit:-4,happy:-3}}]}]});

/* ====================== Shaolin ====================== */
I({id:'sc_sl_sweeper',age:[12,60],tags:CH,only:1,once:1,w:1.4,when:scIs('shaolin'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:4,age:rint(70,95),lv:rint(260,330)});return c},
 text:()=>T('You are sent to help the old monk who sweeps the Sutra Library (藏经阁). He is slow and deaf and nobody knows his name. One morning you notice he sweeps the snow and leaves no footprints in it.','你被派去给藏经阁扫地的老僧打下手。他又慢又聋，谁也不知道他的法号。一天早上你发现，他扫过的雪地上没有一个脚印。'),
 opts:[{l:T('Ask him to teach you','求他指点'),out:[{w:2,t:T('"Teach you to sweep?" He hands you the broom. You sweep for a year, and one day your breathing has changed and you cannot say when.','"教你扫地？"他把扫帚递给了你。你扫了一年，某天发觉呼吸全变了，却说不清是哪天变的。'),c:'gold',fx:{qi:8,merit:4}},{w:1,t:T('He talks to you about attachment, about how a sutra read for power is poison. You do not understand it until you are old.','他跟你讲"执念"，说为争强好胜而读的经书就是毒药。这话你到老才懂。'),c:'good',fx:{align:4,smarts:3,lifespan:1}}]},
  {l:T('Tell the abbot','禀报方丈'),out:[{t:T('The abbot listens, smiles, and says, "Then sweep with him, and say nothing." You do.','方丈听完，微微一笑："那就跟他一起扫，什么也别说。"你照做了。'),c:'muted',fx:{merit:3,qi:3}}]},
  {l:T('Leave him be','由他去'),out:[{t:T('Some mysteries should stay swept. Years later you hear he stopped two grandmasters with one sleeve.','有些谜就让它扫在角落里吧。多年后你听说，他一袖子就制住了两位宗师。'),c:'muted',fx:{merit:2}}]}]});

I({id:'sc_sl_bronze',age:[16,40],tags:CH,only:1,once:1,w:1.5,when:s=>scIs('shaolin')(s)&&power(s)>=20,
 text:()=>T('To go down the mountain as a fighting monk, you must pass the Lane of the Eighteen Bronze Men (十八铜人巷): a dark corridor of monks painted bronze, who do not hold back.','要以武僧身份下山，须闯过十八铜人巷：一条幽暗的长巷，里面是十八位涂成古铜色的武僧，出手绝不留情。'),
 opts:[{l:T('Walk into the lane','闯巷'),fight:FG(PW(1.0,6),'light',T('The Eighteen Bronze Men','十八铜人巷'),T('the Eighteen Bronze Men','十八铜人'),()=>T('the Eighteen Bronze Men','十八铜人')),
   win:[{t:T('You come out the far end with your robe in rags and your head high. The abbot strikes the bell for you.','你从巷子另一头走了出来，僧袍成了布条，头却昂着。方丈为你敲响了钟。'),c:'gold',fx:{merit:10,fame:4,deed:T('Passed the Lane of the Eighteen Bronze Men','闯过少林十八铜人巷')}}],
   lose:[{t:T('You are carried out on a door. The bronze monks visit you that evening with medicine and very good advice.','你是被门板抬出来的。当晚铜人们带着药来看你，还给了些很实在的建议。'),c:'muted',fx:{merit:2,skill:2}}]},
  {l:T('Ask for another year','再练一年'),out:[{t:T('"Wise," says the abbot. "Most who rush the lane are carried out of it."','"明智，"方丈说，"急着闯巷的，多半是被抬出来的。"'),c:'muted',fx:{merit:2,qi:2}}]}]});

I({id:'sc_sl_meat',age:[13,60],tags:CH,only:1,cd:15,when:scIs('shaolin'),ctx:scCtx({sex:'m'}),
 text:c=>T(`Behind the kitchen wall you catch ${c.npc.en}, a monk of your generation, roasting a chicken and sipping wine. He looks up with grease on his chin. "Want a leg?"`,`伙房墙后，你撞见同辈的${c.npc.zh}在烤鸡喝酒。他抬起头，下巴上全是油。"来个鸡腿？"`),
 opts:[{l:T('Report him','禀报戒律院'),out:[{t:T('He is sent to carry water for a year. He grins at you every time he passes. It is unsettling.','他被罚挑一年水。每次路过都冲你咧嘴笑，叫人发毛。'),c:'muted',fx:{merit:4,align:1,meet:'rival',bond:35}}]},
  {l:T('Have a leg','吃一只鸡腿'),out:[{w:2,t:T('It is the best chicken of your life. Amitabha. You chant extra sutras for a month.','这是你这辈子吃过最香的鸡。阿弥陀佛。你多念了一个月的经。'),fx:{happy:5,align:-1,meet:'friend',bond:65}},{w:1,t:T('The Discipline Hall elder rounds the corner. You both carry water for a year.','戒律院的长老正好拐过墙角。你们俩一起挑了一年水。'),c:'bad',fx:{merit:-4,meet:'friend',bond:70}}]},
  {l:T('Lecture him on the precepts','跟他讲戒律'),out:[{t:T('"Wine and meat pass through the gut; the Buddha stays in the heart." He has an answer for everything. You lose the argument and win a friend.','"酒肉穿肠过，佛祖心中留。"他什么都有话说。辩是你辩输了，朋友却交下了。'),c:'muted',fx:{smarts:2,meet:'friend',bond:55}}]}]});

/* ====================== Wudang ====================== */
I({id:'sc_wd_taiji',age:[12,70],tags:CH,only:1,once:1,w:1.4,when:scIs('wudang'),
 text:()=>T('The ancient founder, past a hundred years, comes down from his hermitage to show the young disciples the Taiji forms once. "Watch. Then tell me what you remember."','年过百岁的祖师爷从后山出关，给年轻弟子们演一遍太极。"看好了。然后告诉我你记得多少。"'),
 opts:[{l:T('"I remember all of it."','"弟子全记住了。"'),out:[{t:T('"Good. Now go and forget it." He moves on. You stand there for an hour, puzzled and stung.','"好。现在去把它忘了。"他走开了。你在原地站了一个时辰，又困惑又不服。'),c:'muted',fx:{skill:2,merit:2}}]},
  {l:T('"I remember half."','"记住了一半。"'),out:[{t:T('"Better." He shows it again, slower. Something in the circles makes sense.','"好些。"他又慢慢演了一遍。那一个个圆里，有什么东西对上了。'),c:'good',fx:{skill:3,qi:3,merit:2}}]},
  {l:T('"I have forgotten it all."','"全忘了。"'),out:[{w:s=>s.t.wit,t:T('His eyes light up. "Then you have it." He pushes you lightly with one hand and you feel your whole body turn, like water around a stone.','他眼睛一亮："那你就会了。"他单手轻轻一推，你只觉全身一转，像水流绕过石头。'),c:'gold',fx:{qi:8,skill:4,merit:5}},{w:5,t:T('"You are lying, but cleverly." He laughs and pats your head.','"你在说谎，不过说得聪明。"他笑着摸了摸你的头。'),fx:{happy:3,merit:2}}]}]});

I({id:'sc_wd_crippled',age:[13,55],tags:CH,only:1,once:1,when:scIs('wudang'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:2,sex:'m',age:rint(40,55),lv:rint(5,20)});return c},
 text:c=>T(`One of the old heroes of Wudang, ${c.npc.en}, has lain crippled for twenty years since a treacherous ambush. You are given the duty of caring for him.`,`武当的一位老英雄${c.npc.zh}，二十年前遭人暗算，从此瘫在床上。照料他的差事落到了你头上。`),
 opts:[{l:T('Care for him well','尽心照料'),out:[{w:2,t:T('He cannot move his hands, so he teaches with words: every move of the sword, described, line by line. You learn more lying awake remembering than in any yard.','他双手动不了，便用嘴教：每一式剑招，一句一句地讲。你夜里躺着回想，比在校场上学得还多。'),c:'good',fx:{skill:4,merit:4,meet:'friend',bond:75}},{w:1,t:T('He is bitter and cruel some days. You stay anyway. One night he thanks you, and cries.','有些日子他又苦又刻薄。你还是留下了。有一夜他向你道谢，哭了。'),c:'good',fx:{align:4,merit:4,qi:2}}]},
  {l:T('Ask who did this to him','问是谁害了他'),out:[{t:T('He tells you the name. It is a sect that still exists. You carry the name with you, heavy as a stone.','他说出了那个名字——那个门派至今还在。你把这个名字揣在心里，沉得像块石头。'),c:'muted',fx:{merit:2,flag:'sc_wdgrudge'}}]}]});
QHINT.sc_wdgrudge=T('You know who crippled the old Wudang hero. Nothing has been done.','你知道是谁害残了武当那位老英雄，此仇未报。');

I({id:'sc_wd_birthday',age:[11,70],tags:CH,only:1,cd:6,when:scIs('wudang'),
 text:()=>T('The third day of the third month: the birthday of the True Martial Emperor (真武大帝). Thousands of pilgrims climb to the Golden Summit, and every disciple is on duty.','三月初三，真武大帝圣诞。成千上万的香客登上金顶，弟子们个个当值。'),
 opts:[{l:T('Help the old and lame up the stairs','搀扶老弱上山'),out:[{w:2,t:T('You carry a grandmother up the last hundred steps on your back. She blesses you every year after, at the same spot.','你把一位老婆婆背上了最后一百级台阶。此后每年她都在同一个地方为你祈福。'),c:'good',fx:{merit:4,align:3}},{w:1,t:T('One of the "pilgrims" is a pickpocket. You catch him with a Taiji turn he never sees coming.','有个"香客"是扒手。你一个太极转身就把他拿住了，他到最后都没看明白。'),c:'good',fx:{merit:5,fame:1}}]},
  {l:T('Keep the incense burners','照看香炉'),out:[{t:T('You smell of sandalwood for a month. The donations count is the highest in years.','你身上一个月都是檀香味。今年的香火钱是多年来最多的。'),c:'muted',fx:{merit:3}}]}]});

/* ====================== Emei ====================== */
I({id:'sc_em_abbess',age:[15,40],tags:CH,only:1,once:1,w:1.3,when:scIs('emei'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:scOpp(s),age:clamp(s.age+rint(-1,4),16,45)});return c},
 text:c=>T(`The abbess, whose face has not smiled in thirty years, summons you. "You have been seen with ${c.npc.en}, a disciple of another sect. Emei does not tolerate this. End it, or go."`,`三十年没笑过的师太把你叫了去。"有人看见你和外派弟子${c.npc.zh}来往。峨眉容不得这种事。断了，或者走。"`),
 opts:[{l:T('End it','断了'),out:[{w:2,t:T('You send back a hairpin without a note. The abbess gives you the sect’s second sword form that winter. It does not feel like a reward.','你把一支发簪退了回去，一个字也没写。那年冬天师太传了你本门第二路剑法。这并不像是奖赏。'),c:'muted',fx:{merit:8,skill:2,happy:-6}},{w:1,t:T('You end it, and find you are relieved. That surprises you most of all.','你断了，却发现自己松了口气。这最让你意外。'),fx:{merit:6,qi:2}}]},
  {l:T('Lie: "There is nothing between us."','撒谎："我们没什么。"'),out:[{w:1,t:T('She looks at you for a long time. "Then you will not mind never seeing them again." You mind very much.','她盯着你看了很久。"那你以后再也不见，也无所谓了。"你很有所谓。'),c:'bad',fx:{merit:2,happy:-4}},{w:1,t:c=>T(`She lets it go. You meet ${c.npc.en} by moonlight, more carefully now.`,`她没再追究。你和${c.npc.zh}仍在月下相会，只是更小心了。`),c:'good',fx:{meet:'lover',bond:65,align:-1}}]},
  {l:T('Defend your heart','为心事辩一句'),out:[{w:1,t:T('"Love is not a crime." The abbess slaps you across the hall, and you face the wall for three months. But the next year, a quiet rule is changed.','"情非罪。"师太一巴掌把你扇到大殿另一头，罚你面壁三月。可第二年，有一条门规悄悄改了。'),c:'muted',fx:{merit:-3,align:3,meet:'lover',bond:70}},{w:1,t:c=>T(`"Then go." You walk down the mountain with ${c.npc.en} waiting at the bottom.`,`"那就走吧。"你走下山去，${c.npc.zh}在山脚等着你。`),c:'bad',fx:{meet:'lover',bond:80,happy:4,f:s=>leaveSect(s)}}]}]});

I({id:'sc_em_buddhalight',age:[12,70],tags:CH,only:1,cd:10,when:scIs('emei'),
 text:()=>T('At dawn on the Golden Summit (金顶), the sea of clouds below you catches the sun, and your own shadow appears in a ring of rainbow light: the Buddha’s Halo (佛光).','金顶拂晓，脚下云海映着朝阳，你的影子出现在一圈彩虹般的光环里——峨眉佛光。'),
 opts:[{l:T('Sit and meditate on it','对着佛光打坐'),out:[{w:3,t:T('For the space of a breath you feel no difference between yourself and the cloud. Then it is gone, and your inner energy has deepened.','有一息之间，你觉得自己和云没有分别。然后光环散了，你的内力深了一层。'),c:'good',fx:{qi:5,merit:2}},{w:1,t:T('A nun beside you says the halo only appears for those with karma left to finish. She does not say whether that is good.','身边一位师姐说，佛光只现给尘缘未了的人。她没说那是好是坏。'),c:'muted',fx:{qi:2,smarts:1}}]},
  {l:T('Lean out to touch it','探身去够'),out:[{w:1,t:T('A nun grabs your collar. Pilgrims have jumped, she says, thinking it was a door. You sit back, shaken.','一位师姐一把揪住你的衣领。她说有香客以为那是一扇门，跳了下去。你缩回身子，心有余悸。'),c:'bad',fx:{happy:-2}},{w:2,t:T('The light moves when you move. You laugh like a child. Even the abbess, passing, almost smiles.','你一动，光也动。你笑得像个孩子。路过的师太嘴角差一点就扬起来了。'),c:'good',fx:{happy:5}}]}]});

I({id:'sc_em_sword',age:[16,60],tags:CH,only:1,once:1,when:s=>scIs('emei')(s)&&power(s)>=30,ctx:s=>{const c=scene();c.npc=npc(s,{occ:28,age:rint(25,45),lv:Math.round(power(s)*1.05+4)});return c},
 text:()=>T('Rumour says the abbess keeps the Mountain-Pressing Sword (镇岳剑) in the hall behind the Golden Summit. You are on watch the night a masked thief comes for it.','传言师太把镇岳剑藏在金顶后殿。你值夜那晚，一个蒙面贼摸了进来。'),
 opts:[{l:T('Stop the thief','拦住贼人'),fight:FG((s,c)=>c.npc.lv,'injury',T('The hall behind the summit','金顶后殿'),T('a sword thief','盗剑贼'),()=>T('the masked thief','蒙面贼')),
   win:[{t:T('You tear off the mask: a hired blade from the capital. The abbess says nothing, but you are moved to the inner disciples’ table that night.','你扯下面巾：是京城来的杀手。师太一言不发，当晚却把你的位子挪到了内门弟子那一桌。'),c:'gold',fx:{merit:10,fame:3}}],
   lose:[{t:T('The thief escapes over the roof with a long box. The abbess opens the shrine: the box held a decoy. "You were the test," she says. You are not sure you passed.','贼人带着一只长匣翻上屋顶逃了。师太打开神龛：匣子是个幌子。"你才是被试的那个，"她说。你不确定自己算不算过了。'),c:'muted',fx:{merit:2,hurt:[4,10],cause:T('a sword thief','盗剑贼')}}]},
  {l:T('Raise the alarm','鸣钟示警'),out:[{t:T('Twenty nuns arrive in a breath. The thief does not leave the mountain. You get the credit for sharp ears.','一眨眼来了二十位师姐，贼人没能下山。你落了个"耳朵灵"的功劳。'),c:'good',fx:{merit:6}}]}]});

/* ====================== Mount Hua ====================== */
I({id:'sc_hs_feud',age:[14,60],tags:CH,only:1,once:1,w:1.4,when:scIs('huashan'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(50,70),lv:Math.round(power(s)*1.2+10)});return c},
 text:c=>T(`An old swordsman, ${c.npc.en}, climbs Mount Hua with two companions. He is of the Sword faction (剑宗), driven out by the Qi faction (气宗) twenty-five years ago at the Jade Maiden Peak. "Hand back the master’s seat," he says, "or prove the sword is lesser."`,`一个老剑客${c.npc.zh}带着两个同伴上了华山。他是剑宗的人，二十五年前玉女峰一战被气宗逐出山门。"把掌门之位还来，"他说，"或者证明剑不如气。"`),
 opts:[{l:T('Stand for the Qi faction','为气宗出战'),fight:FG((s,c)=>c.npc.lv,'injury',T('Sword against Qi','剑气之争'),T('the Sword-Qi feud','剑气之争')),
   win:[{t:T('Your breath holds where his blade wavers. He leaves the mountain again. You notice your master did not step forward himself.','他的剑一乱，你的气还稳着。他再次下了山。你注意到，师父自己没有出手。'),c:'gold',fx:{merit:10,fame:4}}],
   lose:[{t:T('His sword is faster than anything you have seen. He spares you. "The Qi men send children now," he says, and leaves you thinking.','他的剑快得你从没见过。他饶了你。"气宗现在派孩子出来了，"他说完就走了，留你在那里想了很久。'),c:'bad',fx:{merit:2,hurt:[6,14],cause:T('a Sword-faction blade','剑宗长剑')}}]},
  {l:T('Ask to hear his side','请他说说自己的道理'),out:[{t:T('He talks until sunset: about brothers who killed each other over a book of notes. You realise both sides are right, and both are fools.','他一直讲到日落：师兄弟为了一本笔记互相残杀。你明白了，两边都有理，两边也都是傻子。'),c:'muted',fx:{smarts:3,skill:2,merit:1,meet:'acq',bond:50}}]}]});

I({id:'sc_hs_cliff',age:[14,45],tags:CH,only:1,once:1,w:1.3,when:scIs('huashan'),
 text:()=>T('For a breach of the rules you are sent to the Wall-Facing Cliff (面壁崖) for a year: a bare ledge, a cave, and a disciple who brings rice once a day.','你犯了门规，被罚上面壁崖一年：一块光秃秃的崖台，一个山洞，每天有个师弟送一回饭。'),
 opts:[{l:T('Explore the cave','探一探山洞'),out:[{w:2,t:T('Behind a thin wall of rock is a hidden chamber, carved with the arts of every sect, and how each one was broken. You do not sleep for a month.','一层薄薄的石壁后藏着一间石室，壁上刻满了各派武功，还刻着每一路是怎么被破的。你一个月没合眼。'),c:'gold',fx:{skill:6,smarts:2,flag:'sc_hscave'}},{w:1,t:T('A skeleton, an axe, and a tunnel dug with that axe over many years. You fill it in, carefully, and do not mention it.','一具骸骨，一把斧头，还有一条用这把斧头挖了不知多少年的地道。你小心地把它填上，没对任何人提起。'),c:'muted',fx:{qi:3}}]},
  {l:T('Practise alone on the ledge','独自在崖上练剑'),out:[{w:2,t:T('Wind, rock, and nobody watching. Your sword gets faster and plainer.','只有风、石头，没人看着。你的剑越来越快，也越来越朴素。'),c:'good',fx:{skill:3,merit:2}},{w:1,t:T('One evening an old man in grey is watching from the rocks. "Too stiff," he says, and is gone before you can bow.','有天傍晚，一个灰衣老人坐在石头上看你。"太拘泥了，"他说。你还没来得及行礼，人已不见了。'),c:'gold',fx:{skill:4,qi:2,flag:'sc_hsoldman'}}]}]});

I({id:'sc_hs_oldman',age:[15,50],tags:CH,only:1,once:1,w:3,need:'sc_hsoldman',when:s=>scIs('huashan')(s)&&s.age-s.flags.sc_hsoldman>=1,
 text:()=>T('The old man in grey is back on the cliff, as if he had never left. "You. The stiff one. Do you want to learn to fight without a form?"','那个灰衣老人又坐在了崖上，仿佛从没离开过。"你，那个拘泥的。想不想学无招胜有招？"'),
 opts:[{l:T('Kneel and say yes','跪下应承'),out:[{w:s=>1+s.t.wit/3,t:T('Nine days. He teaches you to see the flaw in every move, and then forgets you exist. You never learn his name.','九天。他教你看破每一招的破绽，然后就当你不存在了。你始终不知道他的名字。'),c:'gold',fx:{skill:8,unflag:'sc_hsoldman',deed:T('Was taught by a nameless elder on the Wall-Facing Cliff','面壁崖上得无名前辈指点')}},{w:2,t:T('He teaches for three days, then sighs. "Too much in the head." He still leaves you better than he found you.','他教了三天，叹了口气："脑子里东西太多。"可你还是比原先强了。'),c:'good',fx:{skill:4,unflag:'sc_hsoldman'}}]},
  {l:T('Ask who he is','问他是谁'),out:[{t:T('"Nobody. Old Huashan business." He leaves. The ledge feels lonely afterwards.','"没人。华山的陈年旧事罢了。"他走了。崖上从此显得冷清。'),c:'muted',fx:{unflag:'sc_hsoldman',qi:2}}]}]});
QHINT.sc_hsoldman=T('An old man in grey watches from the rocks of the Wall-Facing Cliff.','面壁崖的石头上，有个灰衣老人在看。');

I({id:'sc_hs_plank',age:[13,55],tags:CH,only:1,cd:10,when:scIs('huashan'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([17,1]),age:rint(25,60)});return c},
 text:c=>T(`On patrol along the Plank Walk in the Sky (长空栈道), you find a peddler, ${c.npc.en}, frozen with terror halfway across, hugging the cliff.`,`在长空栈道巡山时，你看见货郎${c.npc.zh}吓僵在半道上，死死抱着崖壁。`),
 opts:[{l:T('Talk him across','一步步哄他过来'),out:[{t:T('An hour, one plank at a time. At the end he gives you a whole box of hairpins. You have no use for them, and treasure them.','一个时辰，一块木板一块木板地挪。到头了，他塞给你一整盒发簪。你用不上，却很珍惜。'),c:'good',fx:{merit:3,align:2,happy:2}}]},
  {l:T('Carry him on your back','背他过去'),out:[{w:s=>1+power(s)/50,t:T('Wind tearing at you, a thousand feet of air below. You make it. Your legs give out on the far side and you both laugh hysterically.','狂风撕扯，脚下是千尺虚空。你过去了。到了对面你腿一软，两个人笑得停不下来。'),c:'good',fx:{merit:5,fame:1,skill:1}},{w:1,t:T('A plank cracks. You leap the gap with him screaming in your ear. Never again.','一块木板裂了。你背着他在耳边的惨叫声里跃过了缺口。再也不干了。'),c:'muted',fx:{merit:5,hurt:[2,6],cause:T('the Plank Walk in the Sky','长空栈道')}}]}]});

/* ====================== Beggars ====================== */
I({id:'sc_bg_factions',age:[13,60],tags:CH,only:1,cd:10,w:1.2,when:scIs('beggar'),
 text:()=>T('At the branch meeting, the Dirty Clothes faction (污衣派), who beg for every meal, and the Clean Clothes faction (净衣派), who own shops and wear silk, are shouting about who sits nearer the chief.','分舵大会上，靠讨饭过日子的污衣派和开铺子穿绸缎的净衣派吵成一团，争谁坐得离帮主近。'),
 opts:[{l:T('Side with the Dirty Clothes','站污衣派'),out:[{w:2,t:T('"A beggar who does not beg is a merchant in rags!" The ragged half of the hall cheers. The silk half remembers your face.','"不讨饭的乞丐，就是穿破衣裳的商人！"衣衫褴褛的那一半齐声叫好，穿绸的那一半记住了你的脸。'),c:'good',fx:{merit:4,align:2,fame:1}},{w:1,t:T('Your speech wins the hall. Your silk-robed elder cuts your rice ration for a year.','你一番话赢了满堂彩。你那位穿绸的长老扣了你一年的口粮。'),c:'muted',fx:{merit:3,happy:-2}}]},
  {l:T('Side with the Clean Clothes','站净衣派'),out:[{t:T('"A gang that cannot pay for medicine cannot protect anyone." They get you a warm coat. The others call you "silk sleeve".','"连药钱都付不起的帮会，护得住谁？"他们给了你一件厚棉袄。另一派从此叫你"绸袖子"。'),c:'muted',fx:{merit:3,money:15}}]},
  {l:T('Propose they take turns','提议轮流坐'),out:[{w:s=>s.smarts/30,t:T('Silence, then laughter, then agreement. The chief taps your shoulder with the green bamboo staff. It is just a tap. You will remember it all your life.','先是安静，然后大笑，最后都同意了。帮主用青竹棒在你肩上轻轻一点。只是一点，你却记了一辈子。'),c:'gold',fx:{merit:7,fame:2}},{w:1,t:T('Both sides turn on you. You eat with the dogs that night.','两派一起朝你开火。那晚你跟狗一起吃的饭。'),c:'bad',fx:{merit:-1,happy:-3}}]}]});

I({id:'sc_bg_junshan',age:[14,70],tags:CH,only:1,once:1,when:scIs('beggar'),
 text:()=>T('The great assembly at Junshan (君山大会): thousands of beggars on an island in Dongting Lake. The chief raises the green bamboo Green Bamboo Staff, and the whole island falls silent.','君山大会：洞庭湖心的岛上聚了成千上万的叫化子。帮主举起那根碧绿的青竹棒，全岛鸦雀无声。'),
 opts:[{l:T('Push to the front to watch','挤到前头去看'),out:[{w:2,t:T('The chief shows one move of the staff to settle a dispute. Twelve elders fall over at once. You will dream about it for years.','帮主为平息争端，使了一招青竹棒法，十二位长老同时摔倒。你好几年都梦见这一招。'),c:'gold',fx:{skill:3,merit:2}},{w:1,t:T('You are squashed against a nine-sack elder who smells of thirty years of roads. He tells you everything about everyone.','你被挤到一位九袋长老身上，他身上是三十年路上的味道。他把每个人的底细都讲给了你听。'),fx:{smarts:2,meet:'acq',bond:55}}]},
  {l:T('Help cook the great pot','帮着煮大锅饭'),out:[{t:T('Beggar’s Chicken for three thousand. The chief comes to the pot, tastes, and calls you by name the next year.','三千人的叫化鸡。帮主走到锅边尝了一口，第二年竟叫得出你的名字。'),c:'good',fx:{merit:5,happy:3}}]}]});

I({id:'sc_bg_sack',age:[14,60],tags:CH,only:1,cd:10,when:scIs('beggar'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:11,age:rint(20,40)});return c},
 text:c=>T(`To earn your next sack, you must beg for a full day in the richest street of the city, and bring back the rule: never steal, never beg from the poor. ${c.npc.en}, a rich young master, throws a silver ingot at your feet, laughing.`,`要多挂一个袋子，你得在城里最富的街上讨一整天饭，守住帮规：不偷，不向穷人讨。富家公子${c.npc.zh}笑着把一锭银子扔在你脚边。`),
 opts:[{l:T('Bow and take it','谢过收下'),out:[{t:T('Twenty taels. You give half to the branch and buy medicine with the rest for an old beggar with a cough.','二十两。你交了一半给分舵，剩下的给一个咳嗽的老叫化买了药。'),c:'good',fx:{merit:4,money:5,align:2}}]},
  {l:T('Kick it back','一脚踢回去'),out:[{w:1,t:T('"Beggars have pride, young sir." The street laughs at him, not you. An elder watching from a doorway puts a mark in his book.','"叫化子也有骨气，少爷。"满街的人笑的是他，不是你。门洞里看着的长老在小本上记了一笔。'),c:'good',fx:{merit:6,fame:1}},{w:1,t:T('His servants beat you. You crawl back to the branch, and the elders are not sure whether to praise you.','他的家丁把你揍了一顿。你爬回了分舵，长老们不知该不该夸你。'),c:'muted',fx:{merit:3,hurt:[3,8],cause:T('a rich man’s servants','富家家丁')}}]}]});

/* ====================== Tang Clan ====================== */
I({id:'sc_tg_cups',age:[12,50],tags:CH,only:1,cd:8,w:1.3,when:scIs('tang'),
 text:()=>T('The poison examination of the Tang Clan: three cups of tea on a table. One is poisoned. You must drink one, and name the poison in the other two.','唐门毒术考：桌上三杯茶，一杯有毒。你须喝下一杯，并说出另两杯里各下的是什么。'),
 opts:[{l:T('Smell them carefully','细细闻'),out:[{w:s=>s.smarts/20+s.t.wit/4,t:T('Bitter almond in the left; nothing in the right, which is the trap; the middle is safe. The examiner smiles very slightly.','左边一杯有苦杏仁味；右边一杯什么味都没有——这才是陷阱；中间那杯是干净的。考官的嘴角动了一动。'),c:'good',fx:{merit:6,smarts:2}},{w:2,t:T('You drink the middle one. It was not the middle one. Three days of fever and an antidote you will be billed for.','你喝了中间那杯。偏偏就是那杯。烧了三天，解药钱还要记你账上。'),c:'bad',fx:{merit:1,hurt:[6,14],cause:T('a Tang poison exam','唐门毒术考'),money:-10}}]},
  {l:T('Drink all three','三杯都喝了'),out:[{w:s=>s.t.root,t:T('You have been taking small doses for years. You name all three poisons through clenched teeth. The elders exchange looks you do not like.','你这些年一直在小剂量地服毒。你咬着牙把三种毒都说了出来。长老们交换了一个让你不太舒服的眼神。'),c:'gold',fx:{merit:10,maxHealth:2,fame:1}},{w:5,t:T('You wake up a week later. "Bold," says the examiner. "Fail."','一个星期后你醒了。"有胆，"考官说，"不及格。"'),c:'bad',fx:{hurt:[10,22],cause:T('three cups of Tang poison','唐门三杯毒茶')}}]},
  {l:T('Switch the cups when no one looks','趁人不备调换杯子'),out:[{t:T('The examiner switched them back while you were switching them. Then again. Everyone in the Tang Clan does this. You pass on cunning alone.','你换杯子的时候，考官也在换。然后又换回来。唐门的人都这么干。你凭着奸猾过了关。'),fx:{merit:4,smarts:1}}]}]});

I({id:'sc_tg_dark',age:[13,50],tags:CH,only:1,cd:10,when:scIs('tang'),
 text:()=>T('The hidden-weapon test: a pitch-black room, an elder somewhere inside with a bag of blunted needles, and you. Catch twelve, or feel them.','暗器考：一间漆黑的屋子，某位长老带着一袋磨钝的针藏在里头。接住十二枚，否则就挨十二针。'),
 opts:[{l:T('Listen for them','凭耳朵听'),out:[{w:s=>1+power(s)/60,t:T('Twelve needles, twelve small sounds, twelve catches. The last one you throw back, and hear a grunt.','十二枚针，十二声细响，接住十二枚。最后一枚你掷了回去，听见了一声闷哼。'),c:'gold',fx:{merit:7,skill:3}},{w:2,t:T('You catch seven. Five find you. You are speckled with bruises for a week, and a little proud.','你接住七枚，挨了五枚。一个星期身上青一块紫一块，心里倒有点得意。'),fx:{merit:3,skill:2,hurt:[2,6],cause:T('blunted needles','钝针')}}]},
  {l:T('Find the elder instead','先去找那位长老'),out:[{w:1,t:T('You follow the sound of breathing and grab a sleeve. "That is not the test," says the elder. "But it is the right answer." Pass.','你循着呼吸声，一把抓住了一只袖子。"考的不是这个，"长老说，"不过答对了。"过关。'),c:'good',fx:{merit:5,smarts:2}},{w:1,t:T('You find a wall, then another wall, then twelve needles.','你摸到一堵墙，又摸到一堵墙，然后挨了十二针。'),c:'bad',fx:{merit:1,hurt:[3,8],cause:T('blunted needles','钝针')}}]}]});

I({id:'sc_tg_outsider',age:[16,60],tags:CH,only:1,once:1,when:s=>scIs('tang')(s)&&s.sur&&s.sur[0]!=='唐',
 text:()=>T('The clan elders meet to decide whether the deeper poison canon may be taught to a disciple whose surname is not Tang. You. You are not invited.','族中长老们开会商议：本门更深的毒经，能不能传给一个不姓唐的弟子——就是你。你没被请去。'),
 opts:[{l:T('Wait for their verdict','静候结果'),out:[{w:1,t:T('"Not yet." The words come down like a door. But one of the elders, a woman with stained fingers, starts leaving notes in your room.','"还不行。"这句话像一扇关上的门。可有位指尖染着药渍的女长老，开始往你屋里塞纸条了。'),c:'muted',fx:{merit:3,smarts:3}},{w:1,t:T('"Yes, on condition you never leave Sichuan." You agree. You will think about that condition for years.','"可以，条件是你终身不出蜀地。"你答应了。这个条件你琢磨了好多年。'),c:'good',fx:{merit:6,skill:2}}]},
  {l:T('Offer to take the Tang name','提出改姓唐'),out:[{t:T('A long silence. Then the eldest laughs. "Not needed. But you have shown us something." You are trusted a little more.','一阵长长的沉默。然后最年长的那位笑了："不必。但你让我们看到了点东西。"他们对你多信了一分。'),c:'good',fx:{merit:5,align:1}}]}]});

/* ====================== Tianshan ====================== */
I({id:'sc_ts_lotus',age:[14,60],tags:CH,only:1,w:2,cd:10,when:scIs('tianshan'),
 text:()=>T('The Snow Lotus (天山雪莲) blooms once in a long while on the glacier above the sect. The elders send you to fetch one before the wind bites it.','天山雪莲隔好多年才在门派上方的冰川上开一回。长老派你赶在寒风啃坏它之前去采。'),
 opts:[{l:T('Climb the glacier','攀上冰川'),out:[{w:3,t:T('You find it at noon, white as a lamp, in a crack of blue ice. The elders brew it for a wounded master. You are allowed the dregs.','正午时你在一道蓝冰缝里找到了它，白得像一盏灯。长老们拿去给一位受伤的师叔熬药，你分到了药渣。'),c:'good',fx:{merit:6,qi:4,heal:20}},{w:1,t:T('A crevasse opens under your feet. You hang from your sword for an hour before you climb out, with frostbitten fingers and the lotus.','脚下裂开一道冰缝。你凭一把剑吊了一个时辰才爬上来，手指冻伤了，雪莲却没丢。'),c:'muted',fx:{merit:6,hurt:[5,12],cause:T('a glacier crevasse','冰川裂缝')}}]},
  {l:T('Eat it yourself','自己吃了'),out:[{w:1,t:T('Heat runs through you like spring water. You feel ten years younger, and the elders never stop wondering where it went.','一股热流像春水般走遍全身，你觉得年轻了十岁。长老们一直纳闷雪莲上哪儿去了。'),c:'gold',fx:{qi:8,lifespan:2,maxHealth:3,align:-3}},{w:1,t:T('They know at once: the smell is on your breath for a month. Three months of glacier duty.','他们一下就知道了：你嘴里一个月都是雪莲味。罚守冰川三个月。'),c:'bad',fx:{qi:5,merit:-6}}]}]});

I({id:'sc_ts_childelder',age:[13,55],tags:CH,only:1,w:2,once:1,when:scIs('tianshan'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:20,sex:'f',age:rint(80,96),lv:rint(250,320)});return c},
 text:c=>T(`A little girl, ${c.npc.en}, no taller than your waist, is ordering the elders about in the main hall. They obey. She has the voice of an old woman. She points at you. "That one. Carry me."`,`大殿上有个小女孩，叫${c.npc.zh}，还不到你腰高，正对着长老们发号施令。长老们竟都听着。她嗓音却是个老婆婆。她一指你："就那个。背我。"`),
 opts:[{l:T('Carry her','背她'),out:[{w:2,t:T('She makes you run up the glacier at night while she shouts breathing instructions in your ear. Your inner energy will never be the same.','她让你夜里背着她往冰川上跑，一路在你耳边喊吐纳的口诀。你的内力从此不一样了。'),c:'gold',fx:{qi:8,merit:4}},{w:1,t:T('She is heavier than a girl should be, and in a foul mood. You are sent to bed bruised and somehow honoured.','她比个孩子该有的分量重多了，脾气还坏。你被打发回去时一身淤青，却莫名觉得很荣幸。'),c:'muted',fx:{merit:3,skill:2}}]},
  {l:T('Ask the elders who she is','问长老她是谁'),out:[{t:T('They go pale. "Do not ask that, ever." She hears, and laughs like a crow.','长老们脸都白了。"永远别问这个。"她听见了，笑得像只老乌鸦。'),c:'muted',fx:{smarts:1}}]}]});

/* ====================== Kunlun ====================== */
I({id:'sc_kl_go',age:[13,60],tags:CH,only:1,w:2,cd:10,when:scIs('kunlun'),
 text:()=>T('A Kunlun master is judged in three things: the zither, the game of go, and the sword. The elder of the hall challenges you to a game of go before you may practise.','昆仑门下讲究琴、棋、剑三绝。主殿长老说，要练剑，先陪他下一盘棋。'),
 opts:[{l:T('Play to win','全力取胜'),out:[{w:s=>s.smarts/25,t:T('You win by half a stone. The elder stares at the board for an hour, then gives you his own sword manual to read.','你赢了半子。长老盯着棋盘看了一个时辰，然后把自己的剑谱借给了你。'),c:'gold',fx:{merit:6,skill:3,smarts:2}},{w:2,t:T('You are crushed in fifty moves. "Your sword will be the same," he says. "Hasty."','五十手你就被屠了大龙。"你的剑也会这样，"他说，"太急。"'),c:'muted',fx:{merit:2,smarts:1}}]},
  {l:T('Play to learn','只求学棋'),out:[{t:T('You lose slowly and ask about every move. He likes you. You start to see the sword the way he sees the board.','你输得很慢，每一手都问个明白。他喜欢你了。你开始像他看棋盘那样看剑。'),c:'good',fx:{merit:3,smarts:3,skill:1}}]}]});

I({id:'sc_kl_caravan',age:[16,60],tags:CH,only:1,w:2,cd:12,when:scIs('kunlun'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:23,age:rint(30,55)});return c},
 text:c=>T(`A jade caravan led by ${c.npc.en} crosses the Kunlun passes under the sect’s protection. In the snow you hear the cough of a snow leopard, very close.`,`${c.npc.zh}的玉石商队在本门护送下翻越昆仑山口。雪地里，你听见一声雪豹的低咳，近在咫尺。`),
 opts:[{l:T('Face the leopard','迎上去'),fight:FG(PW(.95,3),'injury',T('The snow leopard','雪豹'),T('a snow leopard','雪豹'),()=>T('the snow leopard','雪豹'),true),
   win:[{t:T('You drive it off with a cut across the shoulder. The merchant presses a small jade on you, green as a pine.','你一剑划过它的肩头，把它赶走了。商人硬塞给你一块松绿色的小玉。'),c:'good',fx:{merit:6,money:40}}],
   lose:[{t:T('It drags off a mule instead of you. You count yourself lucky, with four long scars.','它最后拖走的是一头骡子而不是你。你自认走运，身上多了四道长疤。'),c:'bad',fx:{merit:2,hurt:[5,12],cause:T('a snow leopard','雪豹')}}]},
  {l:T('Throw it meat and move on fast','扔块肉，快走'),out:[{t:T('The leopard takes the meat and watches you all the way down the pass. Nobody speaks for an hour.','雪豹叼起肉，一路目送你们下了山口。一个时辰里谁也没说话。'),c:'muted',fx:{merit:3}}]}]});

/* ====================== Tide-Listening Isle ====================== */
I({id:'sc_pc_maze',age:[11,50],tags:CH,only:1,cd:8,w:1.2,when:scIs('peach'),
 text:()=>T('The peach groves of the island are planted in a maze by the Five Elements and the Eight Trigrams. Sent to fetch the master’s wine, you have been walking in circles for two hours.','岛上的桃林是按五行八卦栽的阵。你奉命去给岛主取酒，已经转了两个时辰的圈子。'),
 opts:[{l:T('Work out the trigrams','推算卦位'),out:[{w:s=>s.smarts/22,t:T('Kan, then Gen, then three steps on Zhen. The trees open like a door. The master raises an eyebrow at how quickly you came back.','先坎，再艮，震位上走三步。桃树像门一样分开了。岛主见你回得这么快，挑了挑眉。'),c:'good',fx:{merit:4,smarts:3}},{w:1,t:T('Your reckoning leads you to the sea, very precisely. You walk back along the beach.','你算得极准——准准地算到了海边。只好沿着沙滩走回去。'),c:'muted',fx:{smarts:1}}]},
  {l:T('Follow the mute servant','跟着哑仆走'),out:[{t:T('The servant who brings the master’s tea never gets lost. You follow him. He shows you the way with his hands, and a sad smile.','给岛主送茶的哑仆从不迷路。你跟在他身后，他用手比划着给你指路，脸上带着一丝悲凉的笑。'),c:'muted',fx:{merit:3}}]},
  {l:T('Climb a tree and look','爬上树看'),out:[{t:T('From above, the maze is a poem in trees. You sit on a branch until dusk, reading it. The master finds you there and, oddly, is pleased.','从上面看，这阵是用桃树写成的一首诗。你坐在树枝上一直读到天黑。岛主找来时，竟然很高兴。'),c:'good',fx:{smarts:4,merit:2}}]}]});

I({id:'sc_pc_flute',age:[13,60],tags:CH,only:1,once:1,w:1.3,when:scIs('peach'),
 text:()=>T('At midnight the master plays "The Song of the Tides" (潮音曲) on his jade flute, to test the disciples. The music comes in like the tide, and your heart begins to beat to it.','半夜，岛主吹起玉箫奏《潮音曲》，考校弟子的定力。箫声像潮水一样涌来，你的心跳开始跟着它走。'),
 opts:[{l:T('Sit and hold your breath steady','打坐守住呼吸'),out:[{w:s=>s.t.heart,t:T('Wave after wave, and you stay a rock. When the flute stops, the master is standing in your doorway. "Good." Nothing else. That one word is worth a year.','一浪接一浪，你稳如礁石。箫声停时，岛主正站在你门口。"好。"只这一个字，抵得上一年。'),c:'gold',fx:{qi:8,merit:6}},{w:3,t:T('You last until the third wave, then find yourself dancing on the table. You wake on the floor, dizzy and humbled.','你撑到第三浪，回过神时已经在桌上跳舞了。醒来时躺在地上，头晕目眩，心服口服。'),c:'muted',fx:{qi:2,hurt:[2,6],cause:T('the Song of the Tides','潮音曲')}}]},
  {l:T('Stuff your ears with wax','用蜡塞住耳朵'),out:[{t:T('You hear nothing. In the morning the master says only, "Clever. Cowardly." You do not know whether you have passed.','你什么也没听见。早上岛主只说了一句："聪明，胆小。"你不知道自己算不算过关。'),c:'muted',fx:{merit:1,smarts:1}}]},
  {l:T('Answer with your own flute','以箫声相和'),out:[{w:s=>s.smarts/30,t:T('Your little tune bends his tide for a moment. The flute stops. You hear him laugh, really laugh, for the first time.','你那支小曲把他的潮水拨偏了一瞬。箫声停了。你第一次听见他笑，是真笑。'),c:'gold',fx:{merit:7,smarts:2,qi:3}},{w:2,t:T('He drowns you out and you cough blood. "Ambitious," he says, and sends medicine.','他的箫声把你淹没了，你咳了口血。"有志气，"他说，又派人送了药来。'),c:'bad',fx:{hurt:[5,12],cause:T('the Song of the Tides','潮音曲'),merit:2}}]}]});

I({id:'sc_pc_rage',age:[14,50],tags:CH,only:1,once:1,when:scIs('peach'),
 text:()=>T('Pages are missing from a manual in the master’s study. He is in a rage the island has not seen in years. He talks of breaking the legs of every disciple and driving them all off the island, as he did once before.','岛主书房里一本秘籍少了几页。他发了岛上多年未见的雷霆之怒，扬言要把弟子们的腿统统打断，赶出岛去——他从前就这么干过。'),
 opts:[{l:T('Find the missing pages','去找那几页'),out:[{w:s=>s.smarts/25,t:T('They are in his daughter’s sewing basket, used as a pattern. You return them without saying where they were. His rage passes like a storm.','原来在他女儿的针线笸箩里，被拿去当了花样。你把纸送了回去，没说是从哪儿找到的。他的怒气像暴风雨一样过去了。'),c:'gold',fx:{merit:8,smarts:2}},{w:1,t:T('You search everywhere but there. The master calms down by himself after three terrible days.','你哪儿都找了，偏偏没找那儿。熬过可怕的三天，岛主自己消了气。'),c:'muted',fx:{merit:2}}]},
  {l:T('Speak up for your fellows','替同门说话'),out:[{w:1,t:T('"No one here would steal from you." He stares at you, and lets his hand fall. Nobody is driven off.','"这里没有人会偷您的东西。"他盯着你，慢慢放下了手。没有人被赶走。'),c:'good',fx:{merit:5,align:2}},{w:1,t:T('He breaks your arm instead, coldly, and walks away. A week later he sets it himself, without a word.','他冷冷地折了你一条胳膊，转身走了。一个星期后，他亲手给你接上了骨，一个字也没说。'),c:'bad',fx:{hurt:[8,16],cause:T('the master’s rage','岛主之怒'),merit:4}}]}]});

/* ====================== Xuanzhen ====================== */
I({id:'sc_qz_array',age:[13,55],tags:CH,only:1,w:2,cd:6,when:scIs('quanzhen'),
 text:()=>T('The Dipper Sword Array (北斗剑阵) drill: seven Daoists, seven stars. Today you stand at Tianquan, the heart of the array, and one wrong step leaves a hole the size of a man.','北斗剑阵操演：七个道人，七颗星。今天你站天权位——阵眼所在，走错一步，阵里就漏出一个人大的窟窿。'),
 opts:[{l:T('Hold your star','守住星位'),fight:FG(PW(1.0,4),'spar',T('The Dipper Sword Array','北斗剑阵'),T('an array drill','阵法操演'),()=>T('the elder testing the array','试阵的师叔')),
   win:[{t:T('The array holds. The elder testing it is pushed back seven paces and laughs. "Seven of you are worth seventy!"','阵守住了。试阵的师叔被逼退了七步，哈哈大笑："七人可当七十人！"'),c:'good',fx:{merit:6,skill:2}}],
   lose:[{t:T('You step late, and the elder walks right through the hole you left. Seven disciples glare at you all through dinner.','你慢了半步，师叔从你留下的窟窿里大摇大摆地走了出去。七个人瞪了你一整顿晚饭。'),c:'bad',fx:{merit:1,skill:1}}]},
  {l:T('Study the array’s weakness','琢磨阵法的破绽'),out:[{w:s=>s.smarts/30,t:T('You find a flaw when the handle of the Dipper turns. You tell the elders. They change the drill, and your name goes into the array manual.','你发现斗柄转动的那一瞬有个破绽。你禀报了长老，他们改了操法，阵谱上从此有了你的名字。'),c:'gold',fx:{merit:8,smarts:2}},{w:1,t:T('You are so busy thinking that you walk into a fellow’s sword hilt. Black eye.','你光顾着想，一头撞上了师兄的剑柄。眼圈黑了。'),c:'muted',fx:{merit:1}}]}]});

I({id:'sc_qz_tomb',age:[14,50],tags:CH,only:1,w:2,cd:12,when:scIs('quanzhen'),
 text:()=>T('Behind Xuanzhen Palace lies Hidden Orchid Valley, where the women of the valley live. Elders forbid going near. Tonight there is music coming from the hillside.','玄真宫后山就是幽兰谷，幽兰谷的女子住在里面。长辈们严禁靠近。今夜山坡上传来了琴声。'),
 opts:[{l:T('Follow the music','循着琴声去'),out:[{w:1,t:T('A cloud of white bees rises from the grass and you run, stung in eleven places, all the way home.','草丛里飞起一团白色的蜂子，你一路狂奔回去，身上被叮了十一处。'),c:'bad',fx:{hurt:[3,8],cause:T('orchid bees','幽兰蜂'),merit:-1}},{w:1,t:T('A woman in white is playing by a stream. She stops, looks at you, and says, "Xuanzhen? Go home." You do, and never stop wondering.','溪边一个白衣女子在抚琴。她停下手，看了你一眼："玄真观的？回去。"你回去了，却一辈子都在想。'),c:'muted',fx:{happy:3,qi:2}}]},
  {l:T('Report it to the elders','禀报长老'),out:[{t:T('The elders sigh. "That music is old business between the founder and the woman in the valley. Leave it." You sweep the hall extra for asking.','长老们叹了口气："那琴声是祖师和谷里那位的旧事，别管。"你因为多嘴，被罚多扫了一遍大殿。'),c:'muted',fx:{merit:2,smarts:1}}]}]});

/* ====================== Hidden Orchid Valley ====================== */
I({id:'sc_gm_bees',age:[12,50],tags:CH,only:1,w:2,cd:8,when:scIs('gumu'),
 text:()=>T('You tend the orchid bees (幽兰蜂) of the valley: white bees whose honey heals and whose sting makes a strong man scream. Today the queen is restless.','你照看谷中的幽兰蜂：这种白蜂酿的蜜能疗伤，蛰一下却叫铁汉也惨叫。今天蜂王焦躁不安。'),
 opts:[{l:T('Calm them with the whistle','用哨声安抚'),out:[{w:s=>1+s.t.heart/3,t:T('Your whistle rises and falls; the swarm turns in a slow white ring and settles. You feel, for a moment, that you could command them.','你的哨声一起一落，蜂群缓缓绕成一个白环，落了下来。那一刻你觉得自己能号令它们。'),c:'good',fx:{merit:4,qi:3}},{w:1,t:T('A wrong note. They are on you in a cloud. You dive into the cold pool and wait it out.','一个音吹错了。蜂群像一团云扑了上来。你跳进寒潭，憋着气等它们散去。'),c:'bad',fx:{hurt:[4,10],cause:T('orchid bees','幽兰蜂')}}]},
  {l:T('Harvest the honey quietly','悄悄割蜜'),out:[{t:T('A jar of jade honey. The mistress gives you a spoonful, then takes the rest. Your wounds close overnight.','一罐幽兰蜂浆。师父赏了你一勺，余下的收走了。你身上的伤一夜就合上了。'),c:'good',fx:{merit:3,heal:20}}]}]});

I({id:'sc_gm_bed',age:[13,50],tags:CH,only:1,w:2,once:1,when:scIs('gumu'),
 text:()=>T('Your master allows you, at last, to sleep on the Cold Stone Bed (寒石床), carved from jade dug from the bottom of a glacier. One night on it is worth ten nights of meditation, if you survive the cold.','师父终于准你睡寒石床了。那床是用极北冰川底下挖出的寒玉雕成的。在上面睡一夜抵得上打坐十夜——只要你扛得住那份冷。'),
 opts:[{l:T('Sleep on it every night','夜夜睡在上面'),out:[{w:s=>s.t.root,t:T('The first month you shiver till dawn. The second, you sleep. By the third your qi flows like a river in spring.','头一个月你抖到天亮。第二个月睡着了。到第三个月，你的真气像春天的河一样流淌。'),c:'gold',fx:{qi:10,merit:4}},{w:4,t:T('Your fingers go white and stiff. You last a week, then sleep on the floor beside it, and still gain something.','手指冻得发白发僵。你撑了一个星期，后来睡在床边的地上，也还是得了些好处。'),c:'muted',fx:{qi:4,ill:'rheum'}}]},
  {l:T('Use it for meditation by day only','只在白天打坐用'),out:[{t:T('Slow and safe. Your master says nothing, which in the valley is almost praise.','慢，但稳。师父什么也没说——在幽兰谷里，这差不多就是夸奖了。'),c:'good',fx:{qi:5,merit:3}}]}]});

I({id:'sc_gm_vow',age:[16,40],tags:CH,only:1,w:2,once:1,when:s=>scIs('gumu')(s)&&!spouseOf(s),ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:scOpp(s),age:clamp(s.age+rint(-2,4),16,45)});return c},
 text:c=>T(`The rule of the valley: a disciple may not leave it for life, unless someone is willing to die for them. A wounded traveller, ${c.npc.en}, whom you nursed for a month at the valley mouth, comes back and says they are willing.`,`幽兰谷的规矩：弟子终身不得出谷，除非有人愿意为你去死。你在谷口照料过一个月的受伤旅人${c.npc.zh}回来了，说${c.npc.ta}愿意。`),
 opts:[{l:T('Believe them','信了'),out:[{w:2,t:T('Your master is silent for a day, then lets you go to the world for a year. You come back with sun on your face and a lover’s token.','师父沉默了一整天，然后准你出谷一年。你回来时脸上有了阳光，怀里多了一件定情信物。'),c:'good',fx:{meet:'lover',bond:80,happy:8,merit:1}},{w:1,t:T('Your master tests them with a sword at the throat. They do not flinch. Your master turns away. "Go, then. Come back sometimes."','师父把剑架在对方脖子上试了一试，对方眼都不眨。师父转过身去："那就去吧。常回来看看。"'),c:'gold',fx:{meet:'lover',bond:90,happy:10}}]},
  {l:T('Send them away','请对方离开'),out:[{t:T('You close the stone door. For a month you practise more coldly and more perfectly than ever.','你关上了石门。之后一个月，你练功比以往更冷，也更完美。'),c:'muted',fx:{skill:3,merit:3,happy:-5}}]}]});

/* ====================== Sacred Flame Cult ====================== */
I({id:'sc_mj_siege',age:[15,60],tags:CH,only:1,w:2,once:1,when:s=>scIs('mingjiao')(s)&&power(s)>=20,
 text:()=>T('The great sects have united to besiege the Sacred Flame Peak (圣火峰). The cult’s leaders are poisoned or quarrelling. The front gate needs every hand.','各大门派联手围攻圣火峰。教中首脑或中毒、或内讧，前山大门需要每一双手。'),
 opts:[{l:T('Hold the gate','死守山门'),fight:FG(PW(1.05,6),'injury',T('Siege of the Sacred Flame Peak','围攻圣火峰'),T('the siege of the Sacred Flame Peak','圣火峰之战'),()=>T('the sect fighters storming the gate','攻山的六派弟子')),
   win:[{t:T('You hold the gate until dusk. Then a young man with no sect at all walks out between the armies and stops the whole battle by himself. You will tell your grandchildren.','你守住了山门，一直到黄昏。然后一个不属于任何门派的年轻人走到两军之间，一个人止住了整场大战。这件事你会讲给孙子听。'),c:'gold',fx:{merit:10,fame:4,deed:T('Held the gate of the Sacred Flame Peak against the great sects','圣火峰上力拒各大门派')}}],
   lose:[{t:T('You fall at the gate and wake among the wounded. The siege has been lifted by someone you never saw.','你倒在山门前，醒来时躺在伤员中间。围攻已经被一个你没见过的人解了。'),c:'muted',fx:{merit:4,hurt:[6,14],cause:T('the siege of the Sacred Flame Peak','圣火峰之战')}}]},
  {l:T('Carry the wounded through the tunnels','从秘道运送伤员'),out:[{t:T('You learn the secret passages under the summit by heart, carrying men in the dark. Eleven live who would not have.','你在黑暗里背着伤员，把山腹里的秘道走得烂熟。有十一个人因此活了下来。'),c:'good',fx:{merit:8,align:4}}]}]});

I({id:'sc_mj_fire',age:[12,70],tags:CH,only:1,w:2,cd:8,when:scIs('mingjiao'),
 text:()=>T('At the holy fire rite, the brothers chant: "Burn this body, our bodies; flames of the sacred fire. Why be glad in life, why grieve in death? Let us do good and cast out evil." Outside, the poor of the valley have come for rice.','圣火仪式上，教众齐声诵念："焚我残躯，熊熊圣火。生亦何欢，死亦何苦？为善除恶，惟光明故。"外头，山谷里的穷人来领米了。'),
 opts:[{l:T('Give out the rice','去施米'),out:[{w:2,t:T('A widow presses your hand and calls you a bodhisattva. The magistrate would call you a rebel. Both may be true.','一个寡妇攥着你的手叫你活菩萨。县太爷会叫你反贼。两样或许都对。'),c:'good',fx:{merit:4,align:4}},{w:1,t:T('Government soldiers arrive at the end. You lead the crowd away over the hills.','临了官兵来了。你领着人群翻山跑了。'),c:'muted',fx:{merit:5,wanted:1}}]},
  {l:T('Keep the fire through the night','守火通宵'),out:[{t:T('The flame and you, until dawn. You understand, a little, why men die singing.','只有你和火，直到天亮。你有点明白为什么会有人唱着歌赴死了。'),c:'muted',fx:{merit:3,qi:3}}]}]});

/* ====================== Flower Shadow Palace ====================== */
I({id:'sc_yh_man',age:[13,50],tags:CH,only:1,w:2,cd:12,when:scIs('yihua'),ctx:s=>{const c=scene();c.npc=npc(s,{occ:11,sex:'m',age:rint(18,30),lv:Math.round(power(s)*.6)});return c},
 text:c=>T(`A young man, ${c.npc.en}, is found in the palace garden: he climbed the wall to see if the stories were true. By palace law, a man who enters must lose his eyes, or his life.`,`宫中花园里发现了一个年轻男子，叫${c.npc.zh}：他翻墙进来，想看看传说是不是真的。按宫规，擅入的男子要么挖眼，要么偿命。`),
 opts:[{l:T('Bring him before the palace mistress','押去见宫主'),out:[{w:1,t:T('The mistress looks at him a long time and says, "Throw him in the lake. If he swims out, he may keep his eyes." He swims. You never forget his face.','宫主看了他很久："扔进湖里。游得出去，眼睛就留着。"他游出去了。你始终忘不了他那张脸。'),c:'muted',fx:{merit:5}},{w:1,t:T('It is ugly. You do your duty. You do not sleep well for a month.','场面很难看。你尽了本分。之后一个月你都没睡好。'),c:'bad',fx:{merit:6,align:-4,happy:-4}}]},
  {l:T('Let him out by the water gate','从水门放他走'),out:[{w:2,t:T('He kisses your hand and flees. Nobody knows. You find, oddly, that you are smiling.','他吻了一下你的手就逃了。没人知道。你发觉自己竟在笑。'),c:'good',fx:{align:3,happy:3}},{w:1,t:T('The palace knows everything, eventually. A month in the cold cellar.','宫里的事迟早瞒不住。你被关进冰窖一个月。'),c:'bad',fx:{align:3,merit:-6,hurt:[3,8],cause:T('the palace’s cold cellar','花影宫冰窖')}}]}]});

I({id:'sc_yh_twins',age:[12,50],tags:CH,only:1,w:2,cd:10,when:scIs('yihua'),
 text:()=>T('The palace has two mistresses, sisters: the elder, cold as the moon, who never forgives; the younger, gentler, with a crippled hand. Each has asked you to serve her this season.','花影宫有两位宫主，是一对姐妹：大宫主冷若明月，从不饶人；二宫主温和些，一只手有残疾。这一季，两人都要你去伺候。'),
 opts:[{l:T('Serve the elder','伺候大宫主'),out:[{w:2,t:T('A season of perfect silence and perfect form. Once she corrects your palm with a single finger, and your arm goes numb to the shoulder.','一季的绝对安静、绝对规矩。有一次她用一根手指拨正你的掌势，你整条胳膊麻到了肩膀。'),c:'good',fx:{merit:6,skill:3}},{w:1,t:T('You spill a cup of tea. She looks at you. That is all. You are terrified for a month.','你洒了一杯茶。她看了你一眼。仅此而已。你提心吊胆了一个月。'),c:'muted',fx:{merit:2,happy:-3}}]},
  {l:T('Serve the younger','伺候二宫主'),out:[{t:T('She talks to you about the world outside, sadly, as if she once loved someone there. You learn more than palms.','她常跟你讲外面的世界，语气哀伤，像是曾在那里爱过谁。你学到的不只是掌法。'),c:'good',fx:{merit:4,smarts:3,happy:2}}]}]});

/* ====================== more Shaolin / Wudang / Beggar flavour ====================== */
I({id:'sc_sl_bell',age:[11,40],tags:CH,only:1,cd:8,when:scIs('shaolin'),
 text:()=>T('You strike the great bell at dawn: one hundred and eight strokes, one for each worldly trouble. Your arms ache by fifty.','清晨撞钟，一百零八响，一响除一种烦恼。撞到第五十下，你的胳膊就酸了。'),
 opts:[{l:T('Count each stroke with your breath','一响一息地数'),out:[{w:2,t:T('By the hundredth stroke you no longer hear the bell, or feel your arms. Only the sound and the breath.','到第一百响时，你已经听不见钟声，也感觉不到胳膊了。只剩声音和呼吸。'),c:'good',fx:{qi:4,merit:3}},{w:1,t:T('You lose count at seventy and ring a hundred and twelve. The abbot says four extra troubles is about right for you.','数到七十你乱了，撞了一百一十二响。方丈说你多出四种烦恼，倒也合适。'),fx:{merit:2,happy:2}}]},
  {l:T('Ring it as hard as you can','使出全力撞'),out:[{t:T('The whole valley wakes. A crack of thunder answers from the west. The abbot asks you to ring it softer, forever.','整座山谷都被震醒了，西边竟回了一声雷。方丈让你以后永远轻点撞。'),c:'muted',fx:{merit:1,skill:1}}]}]});

I({id:'sc_wd_pine',age:[12,60],tags:CH,only:1,cd:10,when:scIs('wudang'),ctx:scCtx({}),
 text:c=>T(`A storm last night. ${c.sib.en} ${c.npc.en} wants to practise Taiji push-hands on the slippery rocks of the waterfall. "If you can stay balanced here, you can stay balanced anywhere."`,`昨夜一场暴雨。${c.sib.zh}${c.npc.zh}要去瀑布边湿滑的石头上练太极推手。"在这儿站得稳，到哪儿都站得稳。"`),
 opts:[{l:T('Try it','去试试'),fight:FG((s,c)=>c.npc.lv,'spar',T('Push-hands on wet rock','湿石推手'),T('push-hands practice','推手练习')),
   win:[{t:T('They go into the pool, and come up laughing. You stay dry, and something about yielding finally makes sense.','对方掉进了水潭，冒出头来哈哈大笑。你身上干干的。什么叫"舍己从人"，你终于有点懂了。'),c:'good',fx:{skill:2,qi:2,merit:2,meet:'friend',bond:60}}],
   lose:[{t:T('You go into the pool. Cold, but you learned where your root was not.','你掉进了水潭。冷是冷，可你知道了自己的根没扎在哪儿。'),fx:{skill:1,happy:1}}]},
  {l:T('Decline, sensibly','明智地推辞'),out:[{t:T('They go alone and slip in the first minute. You fish them out and get the credit for patience.','对方一个人去了，头一下就滑进了水里。你把人捞上来，落了个"稳重"的名声。'),c:'muted',fx:{merit:2}}]}]});

I({id:'sc_bg_dogs',age:[12,50],tags:CH,only:1,cd:10,when:scIs('beggar'),
 text:()=>T('A rich household has set its dogs on beggars all month. The branch elder hands you a bamboo stick. "The Green Bamboo Staff was made for exactly this. Go and learn something."','有户富人家这个月一直放狗咬叫化子。分舵长老递给你一根竹棍："青竹棒本来就是干这个的。去学点东西。"'),
 opts:[{l:T('Deal with the dogs','对付那几条狗'),fight:FG(PW(.85,2),'light',T('The rich man’s dogs','富户的恶犬'),T('guard dogs','看家恶犬'),()=>T('three mastiffs','三条獒犬'),true),
   win:[{t:T('Three dogs flee yelping, untouched but humiliated. You understand now why the staff’s moves are called "trip", "sweep", and "lead".','三条狗夹着尾巴逃了，没伤着，却丢尽了脸。你这才明白棒法为什么有"绊""挑""引"这些字诀。'),c:'good',fx:{merit:5,skill:2}}],
   lose:[{t:T('You come back with your trousers in shreds. The elder laughs until he coughs, then shows you what you did wrong.','你回来时裤子成了布条。长老笑得直咳嗽，然后把你哪里做错了一一比划给你看。'),c:'muted',fx:{merit:2,skill:1,hurt:[2,6],cause:T('dog bites','狗咬')}}]},
  {l:T('Talk to the master of the house','去找那户主人说理'),out:[{w:1,t:T('He is ashamed, it turns out; his steward set the dogs. He feeds the branch for a month.','原来他也不知情——是管家放的狗。他羞愧之下请分舵吃了一个月的饭。'),c:'good',fx:{merit:5,align:2}},{w:1,t:T('He sets the dogs on you as well.','他连你也一起放狗咬了。'),c:'bad',fx:{hurt:[3,8],cause:T('dog bites','狗咬'),merit:1}}]}]});

/* ====================== senior disciples and elders (rank ≥ 2) ====================== */
I({id:'sc_r_heir',age:[25,70],tags:CH,only:1,once:1,w:1.5,when:s=>scOK(s)&&s.rank>=2&&s.rank<4,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:clamp(s.age+rint(-3,6),20,70),lv:Math.round(power(s)*1.05)});const m=masterOf(s);if(m)c.who=m.id;return c},
 text:c=>T(`Late at night your master asks you, alone: "${c.npc.en}, the eldest disciple, is the obvious heir. Strong, proud, and cruel to the juniors when I am not looking. Tell me honestly. Is he fit?"`,`深夜，师父单独问你："大弟子${c.npc.zh}是众望所归的继承人。武功强，心气高，我不在时对师弟师妹们很刻薄。你老实告诉我，他配不配？"`),
 opts:[{l:T('Tell the truth','实话实说'),out:[{w:2,t:T('Your master nods slowly. The succession is postponed. The eldest never learns why, but somehow suspects you.','师父慢慢点了点头。继位之事暂且搁下。大师兄始终不知原因，却不知怎的怀疑上了你。'),c:'muted',fx:{merit:6,align:3,bond:6,enemy:1}},{w:1,t:T('"I knew. I needed one person to say it." Your master begins, quietly, to teach you the sect’s last secrets.','"我早知道了。我只是需要有一个人说出来。"师父开始悄悄地把本门最后的秘密传给你。'),c:'gold',fx:{merit:10,bond:10,skill:3}}]},
  {l:T('Protect him','替他遮掩'),out:[{t:T('"He will grow into it." The eldest becomes master in time, and remembers your loyalty. The juniors remember something else.','"他会慢慢长进的。"大师兄后来果然接了位，记着你的情分。师弟师妹们记着的是别的。'),c:'muted',fx:{merit:5,align:-2,fame:2}}]},
  {l:T('Say it is not your place','说这不该由你评说'),out:[{t:T('"Coward," says your master, but gently. Nothing changes. Perhaps that was your answer after all.','"胆小，"师父说，语气却很温和。什么都没变。也许这本身就是你的回答。'),c:'muted',fx:{merit:2}}]}]});

I({id:'sc_r_mentor',age:[25,80],tags:CH,only:1,cd:12,w:1.3,when:s=>scOK(s)&&s.rank>=2,ctx:s=>{const c=scene();return scFellow(s,c,{fresh:1,age:rint(14,18),lv:Math.max(5,Math.round(power(s)*.45))})},
 text:c=>T(`The juniors’ instructor gives up on ${c.npc.en}: the most gifted child in years, and the angriest. Bones broken in two fights already. "You take ${c.npc.him}," the elders tell you.`,`教习对${c.npc.zh}没辙了：这孩子是多年来天资最高的，也是火气最大的，已经打断过两个人的骨头。"你来带${c.npc.ta}，"长老们对你说。`),
 opts:[{l:T('Beat the anger out in the yard','在校场上把火气打出来'),fight:FG((s,c)=>c.npc.lv,'spar',T('Taming a wild talent','驯服烈性子'),T('a fierce junior','烈性子的后辈')),
   win:[{t:c=>T(`Every day for a month you put ${c.npc.en} on the ground. One morning ${c.npc.he} bows before starting. That bow is the whole lesson.`,`整整一个月，你天天把${c.npc.zh}摔在地上。有天早上，${c.npc.ta}开打前先行了一礼。这一礼，就是全部的功课。`),c:'good',fx:{merit:8,fame:2,meet:'disciple',bond:65}}],
   lose:[{t:c=>T(`${c.npc.en} beats you. In front of the yard. Then, shocked, helps you up. Something changes in both of you.`,`${c.npc.zh}当着全校场的面打赢了你。然后愣住了，伸手把你扶起来。你们俩心里都有什么东西变了。`),c:'muted',fx:{merit:4,meet:'disciple',bond:55}}]},
  {l:T('Ask what the anger is about','问问这火气从哪儿来'),out:[{w:2,t:c=>T(`A burned village, a family gone, a killer never found. You do not fix it. You listen, for a year. ${c.npc.en} calms, slowly, and calls you teacher.`,`一座被烧的村子，一家人全没了，凶手一直没找到。你没法替${c.npc.ta}了结，只是听，听了一年。${c.npc.zh}慢慢平静下来，开始叫你师父。`),c:'good',fx:{merit:7,align:3,meet:'disciple',bond:75}},{w:1,t:T('"None of your business." The child runs away from the sect a month later. You blame yourself.','"关你什么事。"一个月后，孩子逃出了师门。你怪自己。'),c:'bad',fx:{merit:1,happy:-4}}]}]});

I({id:'sc_r_merge',age:[28,80],tags:CH,only:1,once:1,w:1.4,when:s=>scOK(s)&&s.rank>=2,ctx:s=>{const ks=['shaolin','wudang','emei','huashan','kunlun','quanzhen','songshan','taishan','hengs','hengn','qingcheng','kongtong'].filter(k=>k!==s.sect);const c=scene();c.o=pick(ks);return c},
 text:(c,s)=>T(`A powerful man proposes that ${SECTS[s.sect].en} and ${SECTS[c.o].en} merge into one great sect, "for strength against the dark factions". He would lead it. The elders are split, and your voice may decide.`,`有位权势极大的人物提议，让${SZ(s.sect)}与${SZ(c.o)}并为一派，"好合力对抗邪道"。由他来做掌门。长老们分成了两派，你的一票或许能定乾坤。`),
 opts:[{l:T('Speak against it','力陈其弊'),out:[{w:1.5,t:T('"A sect is its founder’s spirit, not a garrison." The merger fails. The powerful man smiles at you across the hall, and you know you have an enemy.','"门派是祖师的精神，不是一座兵营。"并派之议没成。那位人物隔着大殿冲你一笑，你知道自己结下了一个仇人。'),c:'good',fx:{merit:10,fame:3,align:3,enemy:1}},{w:1,t:T('You win the vote. A month later two elders who backed you are found dead. Nothing can be proved.','你赢了这一票。一个月后，两位支持你的长老被发现死了。什么也查不出来。'),c:'bad',fx:{merit:8,happy:-6,flag:'sc_mergefoe'}}]},
  {l:T('Support the merger','赞成并派'),out:[{t:T('It passes. The new sect is huge and rich, and its leader smiles too much. Your rank is confirmed, and something small in you goes quiet.','提议通过了。新门派又大又富，可那位掌门笑得太多了。你的位子保住了，心里有个小小的东西却沉默了。'),c:'muted',fx:{merit:6,money:100,align:-4}}]},
  {l:T('Ask for time and investigate him','请求缓议，暗中查他'),out:[{w:s=>s.smarts/30,t:T('You find letters linking him to a dark faction. You read them aloud at the meeting. The hall erupts, and he flees by the window.','你查到了他与邪派勾结的书信，在大会上当众念了出来。满殿哗然，他破窗而逃。'),c:'gold',fx:{merit:15,fame:6,deed:T('Unmasked a schemer who would have swallowed the sect','揭破并派阴谋，保全师门')}},{w:1,t:T('You find nothing, and the delay itself kills the plan. Nobody is sure whether you were wise or lucky.','你什么也没查到，可一拖再拖，这事自己黄了。谁也说不清你是英明还是走运。'),c:'muted',fx:{merit:6}}]}]});
QHINT.sc_mergefoe=T('Someone killed the elders who voted with you against the merger.','有人害死了和你一起反对并派的长老。');
I({id:'sc_r_mergefoe',age:[28,85],tags:CH,only:1,once:1,w:6,need:'sc_mergefoe',when:s=>scOK(s)&&s.age-s.flags.sc_mergefoe>=1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(45,65),lv:Math.round(power(s)*1.1+8)});return c},
 text:c=>T(`You finally trace the elders’ murders to ${c.npc.en}, the would-be leader of the merged sect. He is waiting for you in an empty hall, unarmed, smiling. "Shall we be reasonable?"`,`你终于把长老们的死追查到了${c.npc.zh}头上——就是那个想当并派掌门的人。他在空荡荡的大殿里等你，手无寸铁，面带微笑。"咱们讲讲道理？"`),
 opts:[{l:T('Fight him','动手'),fight:FG((s,c)=>c.npc.lv,'injury',T('The empty hall','空殿对决'),T('the schemer of the merger','并派的阴谋家')),
   win:[{t:T('His hidden sword is very fast, and not fast enough. You bring his confession back to the sect, and light incense for the dead.','他藏的剑很快，可还不够快。你把他的供状带回师门，给死去的长老们上了香。'),c:'gold',fx:{merit:12,fame:6,align:4,unflag:'sc_mergefoe',deed:T('Avenged the murdered elders of the sect','为遇害的长老们报了仇')}}],
   lose:[{t:T('He escapes, laughing, and you limp home. But now the whole jianghu knows what he is.','他大笑着逃了，你一瘸一拐地回了山。可如今全江湖都知道他是什么人了。'),c:'muted',fx:{merit:5,unflag:'sc_mergefoe',fame:2}}]},
  {l:T('Listen to his offer','听听他开什么价'),out:[{t:T('Gold, an elder’s seat, a promise. You refuse all three and walk out. He does not trouble you again; you were never worth killing, it seems.','黄金、长老之位、一句承诺。你一样都没要，转身走了。他再没来找你麻烦——看来你还不值得他动手。'),c:'muted',fx:{merit:4,align:2,unflag:'sc_mergefoe'}}]}]});

/* ====================== sect missions (righteous) ====================== */
const scFoeSect=s=>pick(['wudu','sunmoon','xingxiu','xuedao','erengu','qinglong','jinqian','haisha','tiequan','feiying','tuoling','haijiao'].filter(k=>SECTS[k]));
I({id:'sc_m_relic',age:[15,70],tags:SM,only:1,cd:6,when:scOK,
 text:(c,s)=>T(`${SECTS[s.sect].en} is lending a sacred relic, a founder’s sutra in a sandalwood case, to a sister temple three provinces away. You are to carry it, quietly, dressed as a pilgrim.`,`${SZ(s.sect)}要把一件圣物——装在檀木匣里的祖师手抄经——借给三省之外的一座同道寺观。你扮作香客，悄悄护送。`),
 opts:[{l:T('Take the main road and trust your sword','走官道，凭剑说话'),fight:FG(PW(.95,4),'injury',T('Ambush on the pilgrim road','香客道上的埋伏'),T('relic thieves','劫经的盗贼'),()=>foeName()),
   win:[{t:T('Three men with hidden faces jump you in a pine wood. One is left to carry the others away. The relic arrives with its seal unbroken.','松林里跳出三个蒙面人。最后只剩一个，背着另外两个逃了。圣物送到时封条完好。'),c:'good',fx:{merit:8,fame:2,money:20}}],
   lose:[{t:T('They take the case and run. It held a decoy: the real sutra is sewn into your robe. You arrive bruised but successful.','他们抢了匣子就跑。匣里是个幌子——真经缝在你的衣服夹层里。你一身伤，但差事办成了。'),c:'muted',fx:{merit:5,hurt:[4,10],cause:T('relic thieves','劫经的盗贼')}}]},
  {l:T('Take the mountain paths, slow and hidden','走山路，慢而隐秘'),out:[{w:3,t:T('Two months of goat tracks and rain. Nobody sees you. The relic arrives, and so do you, thinner.','两个月的羊肠小道和雨水。没人看见你。圣物到了，你也到了，瘦了一圈。'),c:'good',fx:{merit:6,skill:1}},{w:1,t:T('You get lost and arrive a month late. The temple was robbed in the meantime by the people waiting on the main road for you.','你迷了路，晚到一个月。在此期间，守在官道上等你的那伙人把那座寺抢了。'),c:'muted',fx:{merit:2}}]}]});

I({id:'sc_m_massacre',age:[18,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.e=scFoeSect(s);return c},
 text:c=>T(`A whole village at ${c.place.en} has been slaughtered in one night. The sect sends you to find out who. At the well, someone has painted a symbol in blood: the mark of ${SE(c.e)}.`,`${c.place.zh}一带有个村子一夜之间被屠尽了。师门派你去查。井台上有人用血画了个记号：${SZ(c.e)}的标记。`),
 opts:[{l:T('Look closer before you believe it','先细看，别急着信'),out:[{w:s=>s.smarts/25+s.t.wit/5,t:T('The blood was painted with a brush, by a right-handed scholar. The killers wanted the blame to fall elsewhere. You follow the brush to a respectable family, and justice is slow but real.','这血是用毛笔描的，执笔的是个惯用右手的读书人。凶手是想嫁祸于人。你顺着这支笔查到了一户体面人家，公道来得慢，但终究来了。'),c:'gold',fx:{merit:10,fame:3,align:3}},{w:2,t:T('You find a survivor, a little girl hidden in a rice jar. She cannot say who. You bring her back to the sect.','你找到一个幸存者，一个藏在米缸里的小女孩。她说不出是谁干的。你把她带回了师门。'),c:'muted',fx:{merit:5,align:2}}]},
  {l:T('Follow the trail to the dark faction','顺着标记去追邪派'),fight:FG(PW(1.0,5),'injury',T('Blood on the well','井台血记'),T('a dark faction killer','邪派杀手')),
   win:[{w:1,t:T('You catch a killer of that faction on the road. He swears it was not them, and dies swearing it. You will never know.','你在路上截住一个该派的杀手。他发誓不是他们干的，到死都在发誓。你永远不会知道真相了。'),c:'muted',fx:{merit:6,fame:2}},{w:1,t:T('It was them. You bring back a head and a ledger of names, and the sect posts the names at the gate.','确实是他们。你带回一颗首级和一本名册，师门把名字贴在了山门上。'),c:'good',fx:{merit:9,fame:3}}],
   lose:[{t:T('They were waiting for you. You barely escape, and the trail goes cold.','他们早就在等你了。你死里逃生，线索也断了。'),c:'bad',fx:{merit:0,hurt:[5,12],cause:T('a dark faction ambush','邪派埋伏')}}]}]});

I({id:'sc_m_letter',age:[15,70],tags:SM,only:1,cd:6,when:scOK,ctx:s=>{const ks=Object.keys(SECTS).filter(k=>k!==s.sect&&!SECTS[k].hidden&&!isEvil(k));const c=scene();c.o=pick(ks);c.npc=npc(s,{occ:13,age:rint(25,45),lv:Math.round(power(s)*rint(9,11)/10+3)});return c},
 text:(c,s)=>T(`You are to deliver a formal challenge letter from ${SECTS[s.sect].en} to ${SE(c.o)}, over an old insult. At their gate, a disciple named ${c.npc.en} reads it, tears it up, and spits.`,`你奉命将${SZ(s.sect)}的战书送到${SZ(c.o)}，为的是一桩陈年旧怨。到了山门，一个叫${c.npc.zh}的弟子看完就撕了，还啐了一口。`),
 opts:[{l:T('Demand respect for the letter','要他给战书一个交代'),fight:FG((s,c)=>c.npc.lv,'light',T('A torn letter','撕书之辱'),T('a quarrel at a sect gate','山门前的争执')),
   win:[{t:T('Their master comes out, sees his disciple on the ground, and apologises. He accepts the challenge properly. Your sect is pleased with how you handled it.','对方掌门出来，看见自家弟子趴在地上，当即赔了礼，正式接下了战书。师门对你的处置很满意。'),c:'good',fx:{merit:7,fame:2}}],
   lose:[{t:T('You are thrown down the steps with the pieces of the letter. Your sect is furious, though not entirely at you.','你被连同碎纸一起扔下了台阶。师门大怒——倒也不全是冲你。'),c:'bad',fx:{merit:1}}]},
  {l:T('Ask to see their master','求见对方掌门'),out:[{w:2,t:T('Their master reads the pieces, sighs, and writes a reply that ends the feud. You carry peace home instead of war.','对方掌门把碎片拼起来看完，叹了口气，回了一封信，了结了这段恩怨。你带回的是和，不是战。'),c:'gold',fx:{merit:9,align:3}},{w:1,t:T('You are kept waiting three days, then turned away. Still, you did your duty without bloodshed.','你被晾了三天，然后被打发走了。好在差事办了，也没见血。'),c:'muted',fx:{merit:3}}]}]});

I({id:'sc_m_renegade',age:[18,70],tags:SM,only:1,cd:10,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,age:clamp(s.age+rint(-3,8),18,60),lv:Math.round(power(s)*1.02+3)});return c},
 text:c=>T(`A disciple, ${c.npc.en}, has fled the sect with a manual and the steward’s silver. You track ${c.npc.him} to a farmhouse, where ${c.npc.he} is feeding a sick mother with that silver.`,`弟子${c.npc.zh}卷了一本秘籍和管事的银子逃下山。你一路追到一间农舍，看见${c.npc.ta}正用那些银子给病重的老娘抓药喂饭。`),
 opts:[{l:T('Take the manual, leave the silver','收回秘籍，留下银子'),out:[{w:2,t:T('You report the silver "spent beyond recovery". The manual is back on its shelf. Your conscience is quiet; the steward’s is not.','你回报说银子"已花光，追不回"。秘籍回到了书架上。你问心无愧，管事却不太痛快。'),c:'good',fx:{merit:6,align:4}},{w:1,t:T('The elders find out about the silver and are not amused. But the master quietly sends medicine to the farmhouse.','长老们知道了银子的事，很不高兴。可师父悄悄派人往农舍送了药。'),c:'muted',fx:{merit:3,align:4}}]},
  {l:T('Bring the renegade back','把叛徒押回去'),fight:FG((s,c)=>c.npc.lv,'injury',T('The renegade','追捕叛徒'),T('a renegade disciple','叛门弟子')),
   win:[{t:c=>T(`${c.npc.en} is brought back in chains and crippled by sect law. You get your merit, and the mother’s face stays with you a long time.`,`${c.npc.zh}被锁回山门，按门规废了武功。你得了功劳，那位老娘的脸却在你心里留了很久。`),c:'muted',fx:{merit:9,align:-2,fame:1}}],
   lose:[{t:T('You lose. The renegade binds your wounds, and is gone by morning with the mother on a cart.','你输了。那人给你包扎了伤口，天亮前推着老娘的板车走了。'),c:'bad',fx:{merit:-1,hurt:[4,10],cause:T('a renegade disciple','叛门弟子')}}]},
  {l:T('Let them go entirely','彻底放走'),out:[{w:1,t:T('You report that the trail went cold. Years later a stranger brings you a jar of honey "from a farmhouse".','你回报说线索断了。多年后，一个陌生人给你送来一罐蜂蜜，说是"一户农家送的"。'),c:'muted',fx:{align:3,merit:-2,happy:3}},{w:1,t:T('The truth comes out. You face the wall for half a year.','事情败露了。你被罚面壁半年。'),c:'bad',fx:{align:3,merit:-5}}]}]});

I({id:'sc_m_village',age:[16,70],tags:SM,only:1,cd:6,when:scOK,
 text:c=>T(`Bandits have sent word to a village near ${c.place.en}: forty taels of silver and ten girls by the new moon, or they burn it. The sect sends you and two juniors.`,`山贼给${c.place.zh}附近的一个村子下了帖：新月之前交四十两银子、十个姑娘，不然就烧村。师门派你带两个师弟师妹去。`),
 opts:[{l:T('Meet them head-on','正面迎敌'),fight:FG(PW(1.0,5),'injury',T('Defending the village','保卫村庄'),T('bandits','山贼'),()=>T('the bandit chief','山贼头子')),
   win:[{t:T('The chief goes down in the gate and his men scatter into the hills. The villagers carry you around the square on a door.','山贼头子倒在寨门前，喽啰们四散逃进山里。村民们把你抬在门板上绕着晒谷场转了一圈。'),c:'gold',fx:{merit:9,fame:3,align:3}}],
   lose:[{t:T('You are beaten back, but the juniors get the villagers to the hills. The houses burn. The people live.','你被打退了，可师弟师妹们把村民领上了山。房子烧了，人都活着。'),c:'muted',fx:{merit:4,hurt:[5,12],cause:T('bandits','山贼')}}]},
  {l:T('Train the villagers and lay traps','教村民布陷阱'),out:[{w:s=>s.smarts/30+1,t:T('Pits, nets, and a hundred farmers with bamboo spears. The bandits run into a nightmare and never come back.','陷坑、绳网，再加一百个拿竹枪的庄稼汉。山贼一头撞进了噩梦，再也没回来。'),c:'gold',fx:{merit:10,smarts:2,fame:2}},{w:1,t:T('The traps work on half of them. The other half you fight in the dark, and it is close.','陷阱只拦住了一半，另一半你摸黑硬拼，赢得惊险。'),c:'muted',fx:{merit:7,hurt:[3,8],cause:T('bandits','山贼')}}]},
  {l:T('Pay them off from the sect’s purse','用门派的钱打发'),out:[{t:T('They take the silver and leave. Next year they come back, asking for more. The sect is not pleased.','他们拿了银子走了。第二年又回来了，要得更多。师门很不满意。'),c:'bad',fx:{merit:-2}}]}]});

I({id:'sc_m_manual',age:[18,70],tags:SM,only:1,cd:8,w:1.2,when:scOK,ctx:s=>{const c=scene();c.e=scFoeSect(s);return c},
 text:(c,s)=>T(`A volume of ${SECTS[s.sect].en}’s secret manual was stolen years ago. Now word comes it is kept in a stronghold of ${SE(c.e)}. Get it back.`,`${SZ(s.sect)}多年前失窃的一卷秘籍，如今有消息说藏在${SZ(c.e)}的一处据点里。去把它取回来。`),
 opts:[{l:T('Sneak in at night','夜探据点'),out:[{w:s=>1+s.t.luck/4,t:T('Over the wall, past the dogs, into a library nobody guards because nobody reads. You are out before the second watch with the book in your shirt.','翻墙、绕狗，摸进一间没人守的书房——因为根本没人读书。二更天不到，你已揣着书出来了。'),c:'gold',fx:{merit:10,fame:2}},{w:1,t:T('A guard sees you. You run, with the book and three darts in your back.','被守卫撞见了。你带着书跑了，背上挨了三枚飞镖。'),c:'muted',fx:{merit:8,hurt:[6,14],cause:T('poisoned darts','毒镖'),ill:'inner'}}]},
  {l:T('Walk in and take it','正面闯进去'),fight:FG(PW(1.08,6),'injury',T('The dark stronghold','闯邪派据点'),T('a dark faction stronghold','邪派据点'),()=>T('the hall master','堂主')),
   win:[{t:T('You beat their hall master in his own yard and walk out with the manual under your arm. The jianghu talks of nothing else for a month.','你在对方的院子里击败了堂主，夹着秘籍大步走了出来。江湖上一个月都在谈这件事。'),c:'gold',fx:{merit:10,fame:5,enemy:1}}],
   lose:[{t:T('You are thrown out bleeding. The manual stays where it was. The sect sends someone else next year.','你浑身是血地被扔了出来，秘籍原封不动。明年师门会另派人去。'),c:'bad',fx:{merit:-2}}]},
  {l:T('Buy it through a middleman','托中间人买回来'),cost:120,out:[{w:2,t:T('A hundred and twenty taels, a smoky teahouse, a parcel under the table. The sect repays half and asks no questions.','一百二十两，一间烟雾缭绕的茶馆，桌下递过来一个包袱。师门报销了一半，什么也没问。'),c:'good',fx:{merit:7,money:60}},{w:1,t:T('The parcel holds a cookery book. The middleman is never seen again.','包袱里是一本菜谱。中间人从此人间蒸发。'),c:'bad',fx:{happy:-4}}]}]});

I({id:'sc_m_spring',age:[20,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const ks=Object.keys(SECTS).filter(k=>k!==s.sect&&!SECTS[k].hidden&&!isEvil(k));const c=scene();c.o=pick(ks);c.npc=npc(s,{occ:13,age:rint(35,60),lv:Math.round(power(s)*rint(9,11)/10+2)});return c},
 text:(c,s)=>T(`${SECTS[s.sect].en} and ${SE(c.o)} both claim a hot spring in the valley between them. You are sent to negotiate with their envoy, ${c.npc.en}, before somebody gets killed.`,`${SZ(s.sect)}和${SZ(c.o)}都说两山之间那眼温泉归自己。趁还没出人命，师门派你去和对方的使者${c.npc.zh}谈判。`),
 opts:[{l:T('Propose sharing it by season','提议按季节轮用'),out:[{w:s=>s.smarts/25+1,t:T('Spring and autumn for you, summer and winter for them. You drink to it, and the treaty is carved on a stone by the water.','春秋归你们，夏冬归他们。双方举杯为定，约定刻在了泉边的石碑上。'),c:'gold',fx:{merit:9,fame:2,meet:'acq',bond:55}},{w:1,t:T('They agree, then complain about which seasons. You get a deal, and a headache.','对方同意了，又嫌季节分得不好。协议有了，你的头也疼了。'),c:'muted',fx:{merit:5}}]},
  {l:T('Settle it with a bout','比一场定归属'),fight:FG((s,c)=>c.npc.lv,'spar',T('The hot spring dispute','温泉之争'),T('a sect dispute','门派纠纷')),
   win:[{t:T('The spring is yours. They take it well, mostly. Your juniors go bathing that very night.','温泉归你们了。对方大体上还算服气。当晚师弟师妹们就去泡了。'),c:'good',fx:{merit:7,fame:1}}],
   lose:[{t:T('The spring is theirs. The elders sigh and say you should have talked.','温泉归了对方。长老们叹气，说你该多谈谈的。'),c:'bad',fx:{merit:-1}}]},
  {l:T('Find a second spring','另找一眼泉'),out:[{w:1,t:T('Two days of climbing, and you find one hotter and higher up. Both sects are happy, and you get to name it.','爬了两天，你在更高处找到了一眼更热的泉。两派皆大欢喜，泉还归你命名。'),c:'gold',fx:{merit:8,happy:4}},{w:2,t:T('There is no second spring. There is a bear.','没有第二眼泉，只有一头熊。'),c:'bad',fx:{hurt:[4,10],cause:T('a bear','熊'),merit:1}}]}]});

I({id:'sc_m_rescue',age:[18,70],tags:SM,only:1,cd:8,w:1.2,when:scOK,ctx:s=>{const c=scene();c.e=scFoeSect(s);scFellow(s,c,{fresh:1,age:clamp(s.age+rint(3,12),20,70)});return c},
 text:c=>T(`Your ${c.sib.en}, ${c.npc.en}, has been captured by ${SE(c.e)} and is being held in an old salt warehouse. They want a ransom no sect would pay. You go in.`,`${c.sib.zh}${c.npc.zh}被${SZ(c.e)}抓了，关在一座旧盐仓里。对方要的赎金，没有哪个门派肯付。你去了。`),
 opts:[{l:T('Break in and fight','破门硬闯'),fight:FG(PW(1.05,6),'injury',T('The salt warehouse','盐仓救人'),T('captors in a salt warehouse','盐仓里的看守'),()=>T('the captors','看守')),
   win:[{t:c=>T(`You carry ${c.npc.en} out over your shoulder through smoke and salt. ${c.npc.He} will owe you for the rest of ${c.npc.his} life, and says so every New Year.`,`你扛着${c.npc.zh}穿过烟雾和盐堆冲了出来。这份情${c.npc.ta}要还一辈子，每到过年都要说一遍。`),c:'gold',fx:{merit:10,fame:3,meet:'sworn',bond:85}}],
   lose:[{w:1,t:c=>T('You are beaten, but in the fighting your senior slips the ropes. You both escape, limping, laughing, alive.',`你被打倒了，可混战中${c.sib.zh}挣脱了绳子。你们俩一瘸一拐地逃了出来，又笑又喘，总算活着。`),c:'muted',fx:{merit:5,meet:'friend',bond:75}},{w:1,t:T('You are thrown out. The sect pays the ransom after all, and docks your merit for it.','你被扔了出来。最后还是师门付了赎金，记在了你的账上。'),c:'bad',fx:{merit:-4}}]},
  {l:T('Free them by trickery','智取'),out:[{w:s=>s.smarts/25+s.t.wit/5,t:c=>T('You arrive as a salt inspector with forged papers and a terrible moustache. You leave with "evidence": your senior, in a sack.',`你拿着伪造的公文、贴着一撇蹩脚的胡子，扮成盐官进去。出来时带走了"证物"——装在麻袋里的${c.sib.zh}。`),c:'gold',fx:{merit:10,smarts:2,meet:'friend',bond:80}},{w:1,t:T('The moustache falls off. You run. They move the prisoner. Another try, another year.','胡子掉了。你跑了。他们转移了人质。只能明年再试。'),c:'bad',fx:{merit:0,happy:-3}}]}]});

I({id:'sc_m_famine',age:[16,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(35,55),lv:Math.round(power(s)*.7)});return c},
 text:()=>T('Floods have ruined the river counties. The sect sends you with forty carts of rice. The county magistrate offers to "take charge of distribution".','江边几县遭了水灾。师门派你押四十车米去赈灾。县太爷说可以"代为发放"。'),
 opts:[{l:T('Hand out the rice yourself','亲手发放'),out:[{w:2,t:T('Ten days of ladles and crying children. The sect’s name is blessed in every village on the river.','十天的米勺和孩子的哭声。沿江每个村子都在念师门的好。'),c:'good',fx:{merit:7,align:4,fame:2}},{w:1,t:T('The magistrate’s men try to take the carts. Your stare is enough. Just.','县太爷的人想抢车。你瞪了一眼就够了——刚刚够。'),c:'good',fx:{merit:8,align:3,enemy:1}}]},
  {l:T('Let the magistrate handle it','交给县太爷'),out:[{t:T('Half the rice turns up in the magistrate’s granary. The sect hears about it. So does everyone else.','一半的米进了县太爷的私仓。师门听说了，所有人都听说了。'),c:'bad',fx:{merit:-3,align:-2}}]}]});

I({id:'sc_m_basin',age:[20,70],tags:SM,only:1,cd:10,w:1.1,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(50,65),lv:rint(90,150)});return c},
 text:c=>T(`You represent the sect at the golden-basin ceremony (金盆洗手) of ${c.npc.en}, a famous swordsman retiring from the jianghu. As he lowers his hands to the basin, men with a black flag burst through the gate. "He is friends with a demon. He may not retire."`,`你代表师门去观礼名剑客${c.npc.zh}的金盆洗手。他的手刚要放入金盆，一队打着黑旗的人闯进了大门："他与魔头交好，不准洗手。"`),
 opts:[{l:T('Stand between them and him','挡在他身前'),fight:FG(PW(1.05,6),'injury',T('The golden basin','金盆之变'),T('the black flag envoys','黑旗使者'),()=>T('the envoy of the black flag','黑旗使者')),
   win:[{t:c=>T(`The basin is kicked over, but ${c.npc.en} lives. He takes your hand in both of his. The jianghu hears what you did.`,`金盆被踢翻了，可${c.npc.zh}活了下来。他用双手握住你的手。江湖上都听说了你做的事。`),c:'gold',fx:{merit:9,fame:5,align:4,meet:'friend',bond:80}}],
   lose:[{t:T('You are struck down. When you wake the hall is empty, and the basin is full of blood.','你被打倒了。醒来时大厅空无一人，金盆里盛满了血。'),c:'bad',fx:{merit:2,hurt:[8,16],cause:T('the black flag envoys','黑旗使者'),happy:-6}}]},
  {l:T('Ask to see their proof','要他们拿出凭据'),out:[{w:1,t:T('The "proof" is a letter between two old friends who loved music. Half the guests side with you. The black flag leaves, and will be back.','所谓"凭据"，不过是两个爱好音律的老友间的书信。一半宾客站到了你这边。黑旗走了，但还会回来。'),c:'muted',fx:{merit:6,align:3,smarts:1}},{w:1,t:T('They do not care about proof. You are pushed aside, and what happens next is not your fault, but you carry it.','他们根本不在乎凭据。你被推到一边。接下来发生的事不怪你，可你一直背着它。'),c:'bad',fx:{merit:2,happy:-5}}]},
  {l:T('Stay out of it: it is not your sect’s quarrel','袖手旁观：不是本门的事'),out:[{t:T('You watch. You report back. Your elders say you did right. You do not sleep for a week.','你看着。你回去复命。长老们说你做得对。你一个星期没睡着。'),c:'muted',fx:{merit:3,align:-3,happy:-4}}]}]});

I({id:'sc_m_impostor',age:[16,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:28,age:rint(25,45),lv:Math.round(power(s)*.85)});return c},
 text:(c,s)=>T(`A man calling himself a disciple of ${SECTS[s.sect].en} has been "collecting donations" from shops in the market towns. His name is ${c.npc.en}. The sect wants him stopped.`,`有个自称${SZ(s.sect)}弟子的人，一直在各镇集市上向铺子"化缘"。此人名叫${c.npc.zh}。师门要你去制止他。`),
 opts:[{l:T('Challenge him to show his sect arts','叫他亮一亮本门武功'),fight:FG((s,c)=>c.npc.lv,'light',T('The false disciple','冒牌弟子'),T('an impostor','冒名顶替者')),
   win:[{t:T('His "sect arts" are three street moves and a lot of shouting. The shopkeepers get their silver back.','他的"本门武功"不过是三招街头把式加一通大呼小叫。铺子们的银子都要了回来。'),c:'good',fx:{merit:6,fame:2,money:10}}],
   lose:[{t:T('His street moves are better than your sect moves, today. He escapes. The shame is worse than the bruises.','今天他的街头把式偏偏胜过了你的正宗武功。他跑了。丢人比挨打还难受。'),c:'bad',fx:{merit:-1,happy:-3}}]},
  {l:T('Expose him with a question only a disciple could answer','问一个只有本门弟子才答得上的问题'),out:[{w:s=>s.smarts/30+1,t:T('"What does the old cook put in the New Year soup?" He sweats. The crowd laughs him out of town.','"伙房老厨子过年煮汤放什么？"他满头大汗。围观的人把他笑出了镇子。'),c:'good',fx:{merit:5,smarts:1}},{w:1,t:T('He answers correctly. He was a disciple, once, expelled decades ago. Now it is complicated.','他答对了。他真当过弟子，几十年前被逐出了门墙。这下事情复杂了。'),c:'muted',fx:{merit:3,meet:'acq',bond:40}}]}]});

I({id:'sc_m_plague',age:[18,70],tags:SM,only:1,cd:10,when:scOK,
 text:()=>T('A plague has struck a walled town. The sect has medicine, but the gates are sealed by soldiers who will let nobody in or out.','一座有城墙的县城闹起了瘟疫。师门有药，可城门被官兵封了，谁也不许进出。'),
 opts:[{l:T('Climb the wall at night with the medicine','夜里背药翻城'),out:[{w:3,t:T('Three weeks inside. You carry medicine, bury the dead, and somehow do not fall sick. When the gates open, the town lines the street for you.','在城里待了三个星期。你送药、埋死人，竟没染病。城门开时，全城的人夹道送你。'),c:'gold',fx:{merit:10,align:5,fame:4}},{w:1,t:T('You save many. Then you fall sick yourself.','你救了很多人。然后你自己也病倒了。'),c:'muted',fx:{merit:8,align:5,ill:'lung'}}]},
  {l:T('Persuade the commander','说服守将'),out:[{w:s=>s.smarts/30+.5,t:T('He lets the medicine in by basket, if not you. It is enough to turn the plague.','他准你用竹篮把药吊进去，人不许进。这就够扭转疫情了。'),c:'good',fx:{merit:7,smarts:1}},{w:1,t:T('He will not budge. You go home with full carts and a hollow chest.','他死活不松口。你拉着满车的药回了山，胸口空落落的。'),c:'bad',fx:{merit:1,happy:-4}}]}]});

I({id:'sc_m_flowerthief',age:[18,70],tags:SM,only:1,cd:10,w:1.1,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:11,sex:'m',age:rint(25,40),lv:Math.round(power(s)*1.08+5)});return c},
 text:c=>T(`A notorious "flower thief" (采花贼), ${c.npc.en}, has struck in three towns, the last one under the sect’s protection. He is fast, charming, and laughs at every trap. Bring him in.`,`臭名昭著的采花贼${c.npc.zh}连犯三镇，最后一镇正是本门庇护之地。此人轻功极快，油嘴滑舌，什么陷阱都不放在眼里。把他拿下。`),
 opts:[{l:T('Corner him in an inn and fight','在客栈里堵住他'),fight:FG((s,c)=>c.npc.lv,'injury',T('The flower thief','采花贼'),T('a flower thief’s saber','采花贼的快刀')),
   win:[{t:T('His saber is fast, and you are faster. He is handed to the magistrate, still making jokes. The town sends the sect a plaque.','他的刀快，你的更快。他被交到了县衙，嘴里还在说笑话。镇上给师门送了一块匾。'),c:'gold',fx:{merit:10,fame:4,align:3}}],
   lose:[{t:T('He cuts you thirty times, none of them deep, and leaves laughing. "Do come again." You burn with it for a year.','他在你身上划了三十刀，刀刀不深，大笑着走了："欢迎再来。"你憋了一整年的火。'),c:'bad',fx:{merit:1,hurt:[6,14],cause:T('a flower thief’s saber','采花贼的快刀'),meet:'enemy',bond:5}}]},
  {l:T('Use a bait and a net','设饵张网'),out:[{w:s=>s.smarts/30+1,t:T('A nun’s robe, a rumour of a beautiful pilgrim, and a fishing net soaked in lamp oil. He walks straight in.','一件尼姑袍，一句"有个美貌女香客"的风声，再加一张浸了灯油的渔网。他自己钻了进来。'),c:'gold',fx:{merit:9,smarts:2,fame:2}},{w:1,t:T('He sees the net, cuts it into a hammock, and leaves a thank-you note.','他看穿了网，把它割成了一张吊床，还留了张谢帖。'),c:'muted',fx:{merit:1,happy:-2}}]}]});

I({id:'sc_m_meeting',age:[18,70],tags:SM,only:1,cd:6,w:1.2,when:s=>scOK(s)&&power(s)>=25,ctx:s=>{const ks=Object.keys(SECTS).filter(k=>k!==s.sect&&!SECTS[k].hidden&&!isEvil(k));const c=scene();c.o=pick(ks);c.npc=npc(s,{occ:pick([13,14]),age:clamp(s.age+rint(-3,5),16,60),lv:Math.round(power(s)*rint(95,110)/100+2)});return c},
 text:(c,s)=>T(`You represent ${SECTS[s.sect].en} at a gathering of the righteous sects. In the friendly bouts, you are matched against ${c.npc.en} of ${SE(c.o)}.`,`你代表${SZ(s.sect)}出席正道各派的聚会。切磋时，你的对手是${SZ(c.o)}的${c.npc.zh}。`),
 opts:[{l:T('Fight for the sect’s honour','为师门争光'),fight:FG((s,c)=>c.npc.lv,'light',T('A gathering of the sects','群雄切磋'),T('a bout between sects','门派切磋')),
   win:[{t:T('You win, and your elders sit a little straighter for the rest of the gathering.','你赢了。此后整场聚会，你家长老们的腰都挺得更直了。'),c:'good',fx:{merit:8,fame:4}}],
   lose:[{w:1,t:T('You lose narrowly, with style. Several sects ask about you afterwards.','你惜败，但败得漂亮。事后好几派都来打听你。'),c:'muted',fx:{merit:3,fame:2}},{w:1,t:T('You lose badly. Your elders do not speak to you on the road home.','你输得很难看。回山一路上，长老们没跟你说一句话。'),c:'bad',fx:{merit:-1}}]},
  {l:T('Use the bout to make a friend','借切磋交个朋友'),out:[{t:c=>T(`You fight well and lose gracefully, and spend the evening drinking with ${c.npc.en}. The two sects are on better terms for years.`,`你打得不错，输得体面，晚上又和${c.npc.zh}喝了个痛快。此后多年，两派关系都不错。`),c:'good',fx:{merit:5,meet:'friend',bond:65}}]}]});

I({id:'sc_m_well',age:[16,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:10,age:rint(35,60),lv:Math.round(power(s)*.7)});return c},
 text:c=>T(`The wells of a market town have been poisoned. People are dying. The sect sends you. The town doctor, ${c.npc.en}, has been very busy and very rich lately.`,`有座集镇的井被人下了毒，已经死了人。师门派你去查。镇上的郎中${c.npc.zh}最近忙得很，也阔得很。`),
 opts:[{l:T('Watch the doctor','盯住郎中'),out:[{w:2,t:T('At midnight he drops a paper packet into the temple well. You catch his wrist. The town wants to hang him; you hand him to the magistrate instead.','半夜，他往庙前的井里丢了个纸包。你一把扣住了他的手腕。镇上的人要吊死他，你把他交给了县衙。'),c:'gold',fx:{merit:9,fame:3,align:3}},{w:1,t:T('He is innocent: just a good doctor in a bad year. The real poisoner is a merchant selling water at ten times the price.','他是清白的，不过是坏年景里的好郎中。真正下毒的是一个把水卖到十倍价钱的商人。'),c:'good',fx:{merit:8,smarts:2}}]},
  {l:T('Find an antidote first','先找解药'),out:[{t:T('You test the water on yourself, carefully, until you know the poison. The antidote is a common weed. Hundreds live. The poisoner is never found.','你小心地拿自己试水，终于认出了是什么毒。解药不过是一种常见的野草。数百人得救，下毒的人却始终没找到。'),c:'good',fx:{merit:7,align:4,hurt:[3,8],cause:T('poisoned water','毒水')}}]}]});

I({id:'sc_m_orphan',age:[18,70],tags:SM,only:1,cd:10,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([20,21]),age:rint(7,10),lv:1});return c},
 text:c=>T(`You are to escort ${c.npc.en}, the orphan child of a hero who died for the sect, from the far south back to the mountain. Three different groups want the child, and you do not know why.`,`你奉命把一位为师门殉难的英雄的遗孤${c.npc.zh}从岭南护送回山。有三拨人都在打这孩子的主意，你却不知道为什么。`),
 opts:[{l:T('Travel fast and fight through','快马加鞭，硬闯过去'),fight:FG(PW(1.0,5),'injury',T('The orphan’s road','护孤之路'),T('kidnappers on the road','路上的劫匪'),()=>foeName()),
   win:[{t:c=>T(`You arrive with ${c.npc.en} asleep in your arms. Sewn in the child’s coat is a map. The master burns it unread. "Some things should stay lost."`,`你抱着熟睡的${c.npc.zh}回到了山上。孩子棉袄里缝着一张地图。师父没看就烧了："有些东西就该永远丢着。"`),c:'gold',fx:{merit:10,fame:2,align:3}}],
   lose:[{t:c=>T(`You lose the fight but not the child: you ran with ${c.npc.en} while they argued over the empty cart. Close.`,`仗打输了，孩子却没丢：趁他们为一辆空车争吵，你抱着${c.npc.zh}跑了。好险。`),c:'muted',fx:{merit:6,hurt:[4,10],cause:T('kidnappers on the road','路上的劫匪')}}]},
  {l:T('Disguise the two of you as beggars','你们俩扮成叫化子'),out:[{w:2,t:T('A month of begging along the canals. The child becomes very good at it, and very fond of you.','沿着运河讨了一个月饭。孩子讨得越来越好，也越来越黏你。'),c:'good',fx:{merit:8,meet:'friend',bond:80}},{w:1,t:T('Real beggars object to the competition. It is sorted out with a chicken.','真叫化子嫌你们抢生意。最后用一只鸡摆平了。'),fx:{merit:7,happy:3}}]}]});

I({id:'sc_m_scout',age:[20,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:pick([20,21]),age:rint(9,12),lv:3});return c},
 text:c=>T(`The sect has heard of a remarkable child in a mountain village: ${c.npc.en}, who caught a falling roof beam at nine. You are sent to recruit. The parents want the child to stay and farm.`,`师门听说山里有个奇才：${c.npc.zh}，九岁时接住了一根掉下来的房梁。派你去收徒。孩子的爹娘想让孩子留下种地。`),
 opts:[{l:T('Help with the harvest first','先帮他们收庄稼'),out:[{w:2,t:T('A week of cutting rice beside the family. On the last night the father pours you wine and says, "Take care of my child."','你和这家人一起割了一个星期稻子。最后一晚，孩子的父亲给你斟了酒："孩子就托付给你了。"'),c:'gold',fx:{merit:8,align:2,meet:'disciple',bond:60}},{w:1,t:T('They are grateful, but the answer is still no. You leave a seed of an idea, and a sack of rice.','他们很感激，可还是不肯。你留下了一个念想，和一袋米。'),c:'muted',fx:{merit:3,align:2}}]},
  {l:T('Offer silver','许以银两'),cost:50,out:[{w:1,t:T('They accept, and the child cries all the way up the mountain. You wonder what you have bought.','他们收了。孩子一路哭着上了山。你不禁怀疑自己买下的是什么。'),c:'muted',fx:{merit:6,align:-1}},{w:1,t:T('The mother throws the silver at you. "We are poor, not merchants."','孩子的娘把银子扔回给你："我们穷，可我们不卖孩子。"'),c:'bad',fx:{merit:1}}]},
  {l:T('Let the child choose','让孩子自己选'),out:[{t:T('The child looks at the fields, then at you, then at the fields. "Next year," the child says. You believe it.','孩子看看田，看看你，又看看田。"明年。"孩子说。你信了。'),c:'muted',fx:{merit:3,align:1}}]}]});

I({id:'sc_m_rents',age:[18,70],tags:SM,only:1,cd:8,when:scOK,
 text:(c,s)=>T(`${SECTS[s.sect].en} owns farmland in the valley. You are sent to collect the year’s rent. The harvest was bad, and the tenants are eating bark.`,`${SZ(s.sect)}在山谷里有些田产。你被派去收今年的租子。年景不好，佃户们在啃树皮。`),
 opts:[{l:T('Collect it all, as ordered','照令收齐'),out:[{t:T('You bring back every grain. The steward is delighted. A tenant’s child follows you to the edge of the village, just staring.','你一粒不少地收了回来。管事乐坏了。一个佃户的孩子一直跟到村口，只是盯着你看。'),c:'muted',fx:{merit:6,align:-4}}]},
  {l:T('Forgive this year’s rent','免了今年的租'),out:[{w:1,t:T('The steward rages. The master hears why and says, "Good." The valley sends the sect its best harvest ever the following year.','管事大发雷霆。师父听了缘由，说了一个"好"字。第二年，山谷交上了有史以来最好的一季粮。'),c:'gold',fx:{merit:6,align:5,fame:1}},{w:1,t:T('The steward rages, and the master agrees with him. You are docked merit, and the tenants bless your name.','管事大发雷霆，师父也站在他那边。你被扣了贡献，佃户们却念着你的好。'),c:'muted',fx:{merit:-3,align:5}}]},
  {l:T('Take half, pay half yourself','收一半，另一半自己垫'),cost:40,out:[{t:T('Forty taels of your own. The steward is satisfied, the tenants eat, and only you know.','你自己掏了四十两。管事满意，佃户们有饭吃，只有你自己知道。'),c:'good',fx:{merit:5,align:4}}]}]});

I({id:'sc_m_tiger',age:[16,70],tags:SM,only:1,cd:8,when:scOK,
 text:()=>T('A man-eating tiger has taken three woodcutters on the sect’s mountain. The pilgrims have stopped coming. Kill it.','山上有只吃人的老虎，已经叼走了三个樵夫。香客都不敢来了。去除了它。'),
 opts:[{l:T('Hunt it alone','独自猎虎'),fight:FG(PW(1.0,5),'injury',T('The man-eater','吃人虎'),T('a man-eating tiger','吃人的老虎'),()=>T('the man-eater','吃人虎'),true),
   win:[{t:T('Three days of tracking and one terrible minute. The pelt hangs in the sect’s main hall for a hundred years.','追踪了三天，搏命了一瞬。那张虎皮在大殿里挂了一百年。'),c:'gold',fx:{merit:9,fame:4,deed:T('Killed the man-eating tiger of the sect mountain','只身除掉山上的吃人虎')}}],
   lose:[{t:T('It nearly has you. The woodcutters drive it off with torches and drag you home.','它差一点就得手了。樵夫们举着火把把它赶跑，把你拖了回来。'),c:'bad',fx:{merit:2,hurt:[8,18],cause:T('a man-eating tiger','吃人虎')}}]},
  {l:T('Organise the woodcutters and hunters','召集樵夫猎户围猎'),out:[{w:2,t:T('Drums, fires, and forty men. The tiger is driven into a pit. The village eats well, and the sect looks wise.','锣鼓、火把、四十条汉子。老虎被赶进了陷坑。村里饱餐一顿，师门也显得很英明。'),c:'good',fx:{merit:7,smarts:1}},{w:1,t:T('The tiger breaks through the line. Nobody dies, but the hunt is a shambles.','老虎冲破了包围。没人死，可这场围猎乱成了一锅粥。'),c:'muted',fx:{merit:2}}]}]});

I({id:'sc_m_spy',age:[18,70],tags:SM,only:1,cd:10,w:1.1,when:scOK,ctx:s=>{const c=scene();c.e=scFoeSect(s);return c},
 text:c=>T(`${SE(c.e)} is holding a secret gathering in a ruined temple. The sect wants to know why. You go disguised as a hired hand.`,`${SZ(c.e)}要在一座破庙里秘密聚会。师门想知道为什么。你扮成雇来的杂役混了进去。`),
 opts:[{l:T('Listen and remember','只听不动'),out:[{w:s=>s.t.luck/3+1,t:T('A plot to poison the wells at the next righteous gathering. You slip out at dawn. The plot dies quietly, because of you.','他们密谋在下次正道大会上往井里下毒。你天亮前溜了出来。这桩阴谋因你而悄无声息地破了。'),c:'gold',fx:{merit:10,fame:1,align:3}},{w:1,t:T('Someone notices you do not know the song they all sing. You are out of a window with a dart in your leg, and half the plan.','有人发觉你不会唱他们人人都会的那首歌。你腿上中了一镖，翻窗跑了，只听到了一半。'),c:'muted',fx:{merit:5,hurt:[4,10],cause:T('a poisoned dart','毒镖')}}]},
  {l:T('Steal their leader’s letters','偷取首领的书信'),fight:FG(PW(1.05,5),'injury',T('The ruined temple','破庙夜探'),T('a dark faction guard','邪派守卫')),
   win:[{t:T('The letters name two "righteous" elders on the faction’s payroll. The jianghu shakes for a season.','书信上点了两位"正道"长老的名字，他们都在邪派那里领银子。江湖为此震荡了一整季。'),c:'gold',fx:{merit:10,fame:4,enemy:1}}],
   lose:[{t:T('You are caught and beaten, and thrown in a river. You float home, empty-handed.','你被抓住打了一顿，扔进了河里。你漂回了家，两手空空。'),c:'bad',fx:{merit:0}}]}]});

I({id:'sc_m_ghost',age:[15,70],tags:SM,only:1,cd:8,when:scOK,
 text:()=>T('Pilgrims say a ghost haunts the old shrine on the sect’s road: a white figure, wailing, at midnight. Nobody will use the road. Find out what it is.','香客们说，山道上那座旧神祠闹鬼：半夜有个白影在哭。没人敢走那条路了。去看看是什么东西。'),
 opts:[{l:T('Wait in the shrine at midnight','半夜守在祠里'),out:[{w:2,t:T('The "ghost" is a smuggler in a bedsheet, keeping the road clear for salt carts. You keep the bedsheet as a trophy.','"鬼"是个披着床单的私盐贩子，吓唬人好让盐车过路。床单被你留下当了战利品。'),c:'good',fx:{merit:6,happy:3}},{w:1,t:T('It is a girl hiding from a forced marriage. You help her on her way, and tell the sect the ghost has "moved on".','是个逃婚的姑娘躲在这儿。你送她上了路，回报师门说那鬼"已经超度了"。'),c:'good',fx:{merit:5,align:3}},{w:1,t:T('Nothing comes. At dawn there are small cold footprints all around where you sat. You never mention it.','什么也没来。天亮时，你坐过的地方周围全是小小的、冰凉的脚印。你对谁也没提过。'),c:'muted',fx:{merit:3,qi:2}}]},
  {l:T('Fight whatever comes','来什么打什么'),fight:FG(PW(.85,2),'light',T('The ghost of the shrine','神祠鬼影'),T('the shrine ghost','祠中鬼影'),()=>T('the white figure','白影')),
   win:[{t:T('The ghost goes down with a very human grunt. A bandit lookout, in powder and a wig. The road is open again.','"鬼"挨了一下，发出一声很像人的闷哼——原来是山贼的探子，扑了粉、戴着假发。山道又通了。'),c:'good',fx:{merit:6}}],
   lose:[{t:T('Whatever it is, it is quick, and you run. You do not tell anyone you ran.','不管那是什么，反正很快。你跑了。你没告诉任何人你跑了。'),c:'bad',fx:{merit:1,happy:-3}}]}]});

I({id:'sc_m_hostel',age:[18,70],tags:SM,only:1,cd:8,when:scOK,ctx:s=>{const c=scene();c.npc=npc(s,{occ:11,age:rint(30,50),lv:Math.round(power(s)*.95)});return c},
 text:(c,s)=>T(`Someone has hired thugs to burn the pilgrims’ hostel at the foot of ${SECTS[s.sect].en}’s mountain. The trail leads to ${c.npc.en}, a landlord who wants the land.`,`有人雇了打手，要烧${SZ(s.sect)}山脚下的香客客舍。线索指向地主${c.npc.zh}——他看上了那块地。`),
 opts:[{l:T('Guard the hostel and catch the thugs','守住客舍，抓住打手'),fight:FG(PW(.95,3),'light',T('Fire at the hostel','客舍纵火'),T('hired thugs','雇来的打手'),()=>T('the hired thugs','打手')),
   win:[{t:T('Caught with the oil jars in their hands, they name their employer at once. The landlord pays for a new roof and an apology.','打手们被当场人赃并获，立刻供出了雇主。地主赔了一个新屋顶，外加一声道歉。'),c:'good',fx:{merit:8,money:30}}],
   lose:[{t:T('The hostel burns. Nobody is hurt, and the pilgrims help you rebuild it.','客舍烧了。所幸没人受伤，香客们帮着你重建。'),c:'muted',fx:{merit:3}}]},
  {l:T('Go to the landlord directly','直接去找那地主'),out:[{w:s=>1+s.fame/40,t:T('You explain, politely, which sect owns the hill. He discovers he never wanted the land at all.','你客客气气地说明这座山是哪个门派的。他忽然发觉自己从来就没想要那块地。'),c:'good',fx:{merit:6,fame:1}},{w:1,t:T('He has friends at the yamen. You spend a night in a cell before the sect gets you out.','他在县衙有人。你在牢里蹲了一夜，师门才把你捞出来。'),c:'bad',fx:{merit:1,happy:-4}}]}]});

I({id:'sc_m_grudge',age:[20,70],tags:SM,only:1,once:1,w:5,need:'sc_wdgrudge',when:s=>scIs('wudang')(s)&&s.age-s.flags.sc_wdgrudge>=2&&power(s)>=40,ctx:s=>{const c=scene();c.npc=npc(s,{occ:13,sex:'m',age:rint(50,70),lv:Math.round(power(s)*1.1+8)});return c},
 text:c=>T(`On a mission far from Wudang you meet ${c.npc.en}: the man who crippled the old hero twenty years ago, now grey and rich and respected.`,`在离武当很远的地方办差时，你遇上了${c.npc.zh}——二十年前害残那位老英雄的人。如今他两鬓斑白，家财万贯，受人敬重。`),
 opts:[{l:T('Challenge him openly','当众挑战'),fight:FG((s,c)=>c.npc.lv,'injury',T('The old debt','二十年旧债'),T('an old enemy of Wudang','武当的旧仇人')),
   win:[{t:T('You beat him in front of the whole town and make him say what he did, aloud. Back at Wudang, the old hero weeps when you tell him.','你当着全镇的人击败了他，逼他亲口说出了当年的事。回到武当，老英雄听你讲完，泪流满面。'),c:'gold',fx:{merit:12,fame:5,align:4,unflag:'sc_wdgrudge',deed:T('Avenged a crippled hero of Wudang','为武当前辈讨回公道')}}],
   lose:[{t:T('He beats you, coldly, and has you thrown out of town. But now people are asking questions about him.','他冷冷地击败了你，叫人把你扔出了镇子。可从此有人开始打听他的底细了。'),c:'bad',fx:{merit:3,hurt:[6,14],cause:T('an old enemy of Wudang','武当的旧仇人'),unflag:'sc_wdgrudge'}}]},
  {l:T('Let it go, as a Daoist should','放下，如道家所言'),out:[{t:T('You walk past him. Back on Wudang, the old hero hears and nods. "Good. I let it go years ago. Hatred was the only thing still crippled."','你从他身边走了过去。回到武当，老英雄听说后点了点头："好。我早就放下了。这些年唯一残着的，只有恨。"'),c:'good',fx:{merit:5,qi:5,align:2,unflag:'sc_wdgrudge'}}]}]});
